            nom = "Crisoberilo",
            descriptionCourte = "Grande dureza, aparentado com a alexandrita.",
            descriptionLongue = "Com uma dureza de 8,5, o crisoberilo amarelo-esverdeado é uma das gemas mais resistentes depois do corindo e do diamante. A sua variedade de mudança de cor dá origem à alexandrita, e a sua variedade chatoyant ao olho-de-gato.",
            particularites = "Excelente resistência ao desgaste, ideal para uso diário.",
            inclusions = "Pode apresentar maclas cíclicas características, formando um padrão de estrela de três raios, além de finas inclusões líquidas.",
            lithotherapie = "O crisoberilo é reputado por favorecer o discernimento e atrair a prosperidade nos assuntos pessoais e profissionais."
        ),
        "oeil-de-tigre" to GemTranslation(
            nom = "Olho-de-tigre",
            descriptionCourte = "Chatoyance dourada numa banda móvel.",
            descriptionLongue = "O olho-de-tigre deve a sua chatoyance dourada a fibras de crocidolite (uma variedade de amianto) pseudomorfoseadas em quartzo. Talhado em cabochão, revela uma banda luminosa móvel que se desloca com a luz.",
            particularites = "Sempre talhado em cabochão para revelar a chatoyance (efeito olho-de-gato).",
            lithotherapie = "Pedra de proteção e confiança, o olho-de-tigre é muito utilizado para reforçar a determinação e proteger de influências negativas."
        ),
        "scapolite" to GemTranslation(
            nom = "Escapolite",
            descriptionCourte = "Pouco conhecida, do amarelo-mel ao violeta.",
            descriptionLongue = "A escapolite forma uma série de minerais pouco conhecidos do grande público, talhados em gemas translúcidas amarelo-mel a rosadas. Alguns cristais birmaneses apresentam chatoyance ou fluorescência alaranjada sob UV.",
            particularites = "Algumas pedras birmanesas apresentam um forte efeito olho-de-gato.",
            inclusions = "Inclusões fibrosas paralelas que podem produzir um efeito chatoyant (olho-de-gato) em certas pedras birmanesas.",
            lithotherapie = "A escapolite é associada à disciplina pessoal e à motivação, útil para levar os projetos a bom termo."
        ),
        "malachite" to GemTranslation(
            nom = "Malaquite",
            descriptionCourte = "O verde emblemático do cobre, em bandas concêntricas.",
            descriptionLongue = "A malaquite forma massas botrioidais com bandas concêntricas de verde claro a verde escuro, coloridas pelo cobre. Utilizada desde o Egito antigo como pigmento e pedra ornamental, adorna tanto joias como mobiliário (colunas do Kremlin).",
            particularites = "Sempre talhada em cabochão ou objeto polido; nunca facetada, devido à sua maciez e opacidade.",
            lithotherapie = "Pedra de transformação, a malaquite é reputada por absorver energias negativas e acompanhar suavemente as mudanças de vida."
        ),
        "dioptase" to GemTranslation(
            nom = "Dioptásio",
            descriptionCourte = "Um verde-esmeralda intenso que rivaliza com a própria esmeralda.",
            descriptionLongue = "O dioptásio forma pequenos cristais de um verde-esmeralda tão intenso que rivalizam visualmente com a verdadeira esmeralda, mas a sua grande fragilidade e a sua clivagem perfeita reservam-no quase exclusivamente aos colecionadores.",
            particularites = "Clivagem perfeita e grande fragilidade: a talha facetada é um feito lapidar raramente tentado.",
            inclusions = "Cristais frequentemente associados a dolomite ou calcite da rocha hospedeira; raramente facetado devido à sua clivagem perfeita.",
            lithotherapie = "O dioptásio é associado à cura emocional profunda, favorecendo o perdão e o alívio das feridas do coração."
        ),
        "libethenite" to GemTranslation(
            nom = "Libetenite",
            descriptionCourte = "Um fosfato de cobre hidratado verde-oliva a verde-escuro, mineral raro de coleção.",
            descriptionLongue = "A libetenite forma pequenos cristais prismáticos ou piramidais de um verde-oliva a verde-escuro, quase negro, reunidos em agregados drusiformes sobre uma matriz oxidada. Descoberta no século XIX em Ľubietová (outrora Libethen), na Eslováquia, que lhe dá o nome, forma-se na zona de oxidação de jazigos cupríferos, frequentemente junto à malaquite e a outros fosfatos de cobre. A sua talha facetada continua excecional: é, acima de tudo, um mineral de coleção.",
            particularites = "Mineral secundário da zona de alteração dos jazigos de cobre, frequentemente associado à malaquite e a outros fosfatos de cobre; a sua raridade torna-o uma peça quase exclusivamente reservada aos colecionadores de minerais.",
            lithotherapie = "A libetenite é por vezes associada em litoterapia ao enraizamento e à regeneração, na continuidade dos minerais cupríferos reputados energizantes."
        ),
        "amazonite" to GemTranslation(
            nom = "Amazonite",
            descriptionCourte = "Um verde-azulado opaco estriado de branco, apesar de o nome não ter qualquer ligação com a Amazónia.",
            descriptionLongue = "A amazonite é uma variedade de microclina verde-azulada opaca, estriada de veios brancos. O seu nome evoca o rio Amazonas, embora nunca ali tenha sido confirmado qualquer jazigo histórico — um dos mistérios persistentes da mineralogia.",
            particularites = "Sempre talhada em cabochão devido à sua opacidade; sensível a choques ao longo dos seus planos de clivagem.",
            inclusions = "Estrutura em maclas polissintéticas responsável pelo seu aspeto listado verde-azulado característico, por vezes atravessada por finos veios brancos de quartzo ou albite.",
            lithotherapie = "Pedra apaziguadora, a amazonite é reputada por acalmar o stress e facilitar uma comunicação sincera com os outros."
        ),
        "chrysoprase" to GemTranslation(
            nom = "Crisoprásio",
            descriptionCourte = "O verde-maçã mais vivo da família das calcedónias.",
            descriptionLongue = "O crisoprásio é a variedade de calcedónia com a cor verde-maçã mais intensa, colorida por vestígios de níquel. Apreciado desde a Antiguidade, conheceu um renascimento no século XVIII, nomeadamente no mobiliário de Frederico, o Grande, da Prússia.",
            particularites = "A cor pode desvanecer-se com a desidratação prolongada ou com o calor intenso; conserva-se melhor ligeiramente húmida.",
            inclusions = "Coloração verde resultante do níquel disperso na sílica microcristalina; pode apresentar finas veias esbranquiçadas.",
            lithotherapie = "O crisoprásio é tradicionalmente associado à esperança e ao otimismo, abrindo o coração a novas perspetivas."
        ),
        "beryl-vert" to GemTranslation(
            nom = "Berilo verde",
            descriptionCourte = "O verde «comum» do berilo, sem o crómio que faria dele uma esmeralda.",
            descriptionLongue = "Colorido pelo ferro em vez do crómio ou do vanádio, o berilo verde não tem direito à denominação «esmeralda» em gemologia estrita, mas oferece pedras limpas e luminosas a um preço bem mais acessível.",
            particularites = "Distinguido da esmeralda pelo espetroscópio: ausência das linhas de absorção do crómio/vanádio.",
            inclusions = "Inclusões de tubos ocos paralelos e ocasionais cristais minerais acessórios; geralmente muito limpo a olho nu.",
            lithotherapie = "O berilo verde é reputado por trazer equilíbrio emocional e renovação, ajudando a virar a página após um período difícil."
        ),
        "sillimanite" to GemTranslation(
            nom = "Silimanite",
            descriptionCourte = "Uma prima pouco conhecida da andaluzita e da cianite, por vezes com olho-de-gato.",
            descriptionLongue = "Polimorfo da andaluzita e da cianite (mesma fórmula, estrutura cristalina diferente), a silimanite apresenta-se em verde-azulado a castanho, por vezes com um efeito chatoyant procurado em cabochão.",
            particularites = "Pode apresentar um efeito olho-de-gato muito nítido quando talhada em cabochão perpendicularmente às fibras.",
            inclusions = "Inclusões fibrosas que podem produzir um efeito chatoyant (olho-de-gato) em pedras talhadas em cabochão.",
            lithotherapie = "A silimanite é associada à clareza mental, um apoio para pôr ordem nos pensamentos e nas prioridades."
        ),
        "seraphinite" to GemTranslation(
            nom = "Serafinite",
            descriptionCourte = "Um verde profundo atravessado por penas prateadas sedosas.",
            descriptionLongue = "A serafinite, nome comercial de uma variedade de clinocloro, apresenta motivos plumosos prateados sobre fundo verde-escuro, evocando asas de anjo — daí o seu nome. Sempre trabalhada em cabochão polido para revelar este brilho sedoso.",
            particularites = "Extremamente macia: a reservar para joias pouco expostas a choques (pendentes, brincos).",
            lithotherapie = "Pedra de cura profunda, a serafinite é reputada por ajudar a libertar padrões repetitivos e a iniciar uma renovação interior."
        ),
        "grenat-grossulaire" to GemTranslation(
            nom = "Granada grossulária",
            descriptionCourte = "A granada verde a verde-amarelada, prima pouco colorida da tsavorite e da hessonita.",
            descriptionLongue = "A grossulária cobre uma vasta gama do incolor ao verde intenso, passando pelo verde-amarelado («granada do Mali»), consoante os vestígios de ferro, manganês ou vanádio presentes — a tsavorite e a hessonite são as suas variedades mais célebres.",
            particularites = "A família de granadas com maior diversidade de cores, do incolor ao verde profundo da tsavorite.",
            inclusions = "Cristais acessórios variáveis consoante o jazigo, com halos de tensão em torno de pequenos cristais incluídos.",
            lithotherapie = "A granada grossulária é associada à abundância e à vitalidade, um apoio nos períodos de reconstrução pessoal."
        ),
        "diopside" to GemTranslation(
            nom = "Diópsido de crómio",
            descriptionCourte = "Um verde-pinheiro profundo devido ao crómio, primo da granada demantoide.",
            descriptionLongue = "O diópsido de crómio deve o seu verde intenso, próximo do da esmeralda, a vestígios de crómio. Encontrado nos mesmos jazigos que os diamantes (kimberlitos), serve por vezes de mineral indicador para os prospetores.",
            particularites = "Dureza reduzida, exigindo cuidado em joalharia; algumas pedras apresentam asterismo ou efeito olho-de-gato.",
            inclusions = "Finas inclusões em agulhas negras (magnetite ou cromite) e cristais acessórios por vezes visíveis à lupa.",
            lithotherapie = "O diópsido de crómio é reputado por favorecer a ligação à natureza e o equilíbrio emocional do quotidiano."
        ),
        "jade-nephrite" to GemTranslation(
            nom = "Jade nefrita",
            descriptionCourte = "O jade histórico da China e da Nova Zelândia, distinto da jadeíte.",
            descriptionLongue = "Antes da descoberta da jadeíte birmanesa no século XVIII, todo o jade trabalhado na China imperial, na Nova Zelândia (pounamu maori) e na América pré-colombiana era nefrita — uma anfíbola entrelaçada em fibras microscópicas que lhe confere uma tenacidade excecional.",
            particularites = "Uma estrutura de fibras feltradas que a torna mais resistente a choques do que a jadeíte, apesar de uma dureza ligeiramente inferior.",
            lithotherapie = "Pedra de sabedoria e harmonia desde a antiga China, o jade nefrita é reputado por trazer serenidade, proteção e longevidade."
        ),
        "maw-sit-sit" to GemTranslation(
            nom = "Maw-sit-sit",
            descriptionCourte = "Um verde elétrico veado de negro, com o nome de uma aldeia birmanesa.",
            descriptionLongue = "O maw-sit-sit, nomeado a partir da aldeia birmanesa onde foi descoberto em 1963, é uma rocha dominada pela jadeíte e pela kosmochlor (um piroxena crómico) que oferece um verde vivo atravessado por veios negros, muito apreciado na Ásia.",
            particularites = "O único jazigo conhecido no mundo até hoje, situado nas proximidades das minas de jadeíte de Hpakant.",
            lithotherapie = "O maw-sit-sit é associado à renovação e à circulação de uma energia positiva nos momentos de transição."
        ),
        "tourmaline-chrome" to GemTranslation(
            nom = "Turmalina crómica",
            descriptionCourte = "Um verde profundo e saturado devido ao crómio e ao vanádio, distinto do verde «clássico».",
            descriptionLongue = "Colorida pelo crómio e pelo vanádio em vez do ferro, a turmalina crómica apresenta um verde mais saturado e profundo do que a turmalina verde comum, com um dicroísmo marcado entre verde e verde-acastanhado consoante o ângulo de observação.",
            particularites = "Dicroísmo marcado: a orientação da mesa é determinante para revelar a tonalidade mais saturada.",
            inclusions = "Finas tricites e ocasionais inclusões cristalinas, comparáveis às restantes turmalinas verdes.",
            lithotherapie = "A turmalina crómica é reputada por estimular a vitalidade, favorecendo simultaneamente a abertura do coração e a compaixão."
        ),
        "saphir-vert" to GemTranslation(
            nom = "Safira verde",
            descriptionCourte = "Um verde discreto, frequentemente dicroico, a cor mais acessível do corindo.",
            descriptionLongue = "Colorida pelo ferro, a safira verde apresenta frequentemente um nítido dicroísmo (verde e verde-amarelado consoante o ângulo), uma assinatura que ajuda a distingui-la de outras gemas verdes. É geralmente a cor mais acessível entre as safiras.",
            particularites = "Dicroísmo marcado entre verde e verde-amarelado consoante o eixo de observação, útil para a identificação.",
            inclusions = "Zonamento de cor característico em bandas paralelas, seda de rútilo fina e cristais minerais acessórios típicos do corindo.",
            lithotherapie = "A safira verde é associada ao equilíbrio interior e à sabedoria, um apoio para ganhar distância e perspetiva."
        ),
        "emeraude" to GemTranslation(
            nom = "Esmeralda",
            descriptionCourte = "O verde mais procurado da alta joalharia.",
            descriptionLongue = "A esmeralda deve o seu verde profundo ao crómio e/ou ao vanádio. As suas inclusões naturais, apelidadas de «jardim», atestam a sua autenticidade e são geralmente estabilizadas com um tratamento a óleo de cedro, uma prática aceite e esperada no mercado.",
            particularites = "O tratamento a óleo é quase universal; pedra frágil que exige cuidados na manipulação.",
            inclusions = "«Jardim»: inclusões multifásicas características (líquido, gás, cristal), cristais de pirite (Colômbia), de actinolite ou de mica; fissuras naturais tipicamente preenchidas com óleo de cedro.",
            lithotherapie = "Pedra de amor e sabedoria, a esmeralda é tradicionalmente reputada por aliviar tensões emocionais e favorecer a fidelidade e a harmonia nas relações."
        ),
        "peridot" to GemTranslation(
            nom = "Peridoto",
            descriptionCourte = "Verde-oliva luminoso, nunca tratado.",
            descriptionLongue = "O peridoto é uma das poucas gemas compostas por uma única espécie mineral (a olivina) e nunca é tratado. A sua forte birrefringência pode, por vezes, tornar visível a olho nu o duplicado das arestas através da mesa da pedra.",
            particularites = "Birrefringência visível a olho nu; algumas pedras provêm de meteoritos (palasitos).",
            inclusions = "Frequentes inclusões de cromite negra rodeadas por um disco de tensão apelidado de «nenúfar», acompanhadas de finos cristais de mica biotite.",
            lithotherapie = "O peridoto é associado ao bem-estar geral e ao desapego, ajudando a libertar rancores e ressentimentos."
        ),
        "tsavorite" to GemTranslation(
            nom = "Tsavorite",
            descriptionCourte = "Uma alternativa sustentável e não tratada à esmeralda.",
            descriptionLongue = "Descoberta em 1967 perto do Parque Nacional de Tsavo, no Quénia, a tsavorite deve a sua cor verde ao vanádio e ao crómio. Sempre não tratada, oferece um brilho e uma pureza frequentemente superiores aos da esmeralda.",
            particularites = "Nunca tratada; jazigos limitados que tornam as pedras grandes muito raras.",
            inclusions = "Finas fibras e cristais acessórios (frequentemente magnetite ou grafite); as pedras do leste africano são geralmente de boa pureza.",
            lithotherapie = "A tsavorite é reputada por estimular a vitalidade e a confiança em si mesmo, um apoio para enfrentar desafios com energia."
        ),
        "jade-jadeite" to GemTranslation(
            nom = "Jade (jadeíte)",
            descriptionCourte = "A pedra sagrada da cultura chinesa.",
            descriptionLongue = "A jadeíte forma um agregado microcristalino de tenacidade excecional, o que a distingue da nefrita, o outro mineral chamado «jade». Venerada na China como «pedra do céu», simboliza a pureza e a virtude.",
            particularites = "Extremamente tenaz apesar de uma dureza moderada; a qualidade «imperial», um verde translúcido muito raro.",
            lithotherapie = "O jade jadeíte é reputado por trazer sorte e proteção, favorecendo simultaneamente a harmonia nas relações e a serenidade interior."
        ),
        "tourmaline-verte" to GemTranslation(
            nom = "Turmalina verde (Verdelite)",
            descriptionCourte = "Verde colorido pelo ferro ou pelo crómio.",
            descriptionLongue = "A verdelite cobre uma vasta gama de verdes, do verde-menta claro ao verde-floresta profundo, consoante os vestígios de ferro, crómio ou vanádio. O seu forte pleocroísmo pode fazer variar sensivelmente a sua tonalidade consoante o ângulo de talha.",
            particularites = "Forte birrefringência; os talhadores orientam o bruto para otimizar a cor.",
            inclusions = "Tricites em fios de algodão, tubos ocos paralelos ao eixo c e, por vezes, zonamento de cor visível.",
            lithotherapie = "A turmalina verde é associada ao equilíbrio emocional e à regeneração, um apoio após um período de fadiga moral."
        ),
        "demantoide" to GemTranslation(
            nom = "Granada demantoide",
            descriptionCourte = "Dispersão superior à do diamante.",
            descriptionLongue = "A demantoide é a variedade verde mais apreciada da granada andradita, colorida pelo crómio. A sua dispersão (o «fogo») supera a do diamante, e as suas inclusões fibrosas em «cauda de cavalo» (bissolite) são uma marca de autenticidade procurada pelos colecionadores.",
            particularites = "Dispersão ótica excecional; inclusões em «cauda de cavalo» características das pedras dos Urais.",
            inclusions = "Inclusões fibrosas radiadas em «cauda de cavalo» (bissolite), assinatura das pedras dos Urais e marca de autenticidade muito procurada.",
            lithotherapie = "A granada demantoide é reputada por atrair a prosperidade e reavivar a alegria quotidiana."
        ),
        "uvarovite" to GemTranslation(
            nom = "Granada uvarovite",
            descriptionCourte = "Verde-esmeralda em drusas de microcristais.",
            descriptionLongue = "A uvarovite forma quase sempre minúsculos cristais em drusas, raramente suficientemente grandes para serem facetados. O seu verde-esmeralda intenso, devido ao crómio, faz dela ainda assim uma peça de coleção muito procurada em estado bruto.",
            particularites = "Cristais quase sempre demasiado pequenos para a talha facetada; coleccionada em bruto em drusa.",
            inclusions = "Apresenta-se geralmente em minúsculos cristais drusiformes; as inclusões internas continuam pouco documentadas devido ao seu tamanho reduzido.",
            lithotherapie = "A uvarovite é associada ao apaziguamento e a uma melhor ligação com a natureza envolvente."
        ),
        "vesuvianite" to GemTranslation(
            nom = "Vesuvianite (idocrásio)",
            descriptionCourte = "Descoberta nas encostas do Vesúvio.",
            descriptionLongue = "Descrita pela primeira vez nas escoadas do Vesúvio, a vesuvianite (ou idocrásio) oferece tonalidades verde-oliva a verde-garrafa. A sua variedade maciça e compacta, a californite, é por vezes utilizada como substituto do jade.",
            particularites = "A variedade maciça californite pode imitar o jade nefrita.",
            inclusions = "Finas inclusões granulares e cristais acessórios consoante o jazigo, conferindo frequentemente uma estrutura interna ligeiramente enevoada.",
            lithotherapie = "A vesuvianite é reputada por encorajar a superação de si mesmo e estimular a criatividade em projetos pessoais."
        ),
        "prehnite" to GemTranslation(
            nom = "Prenite",
            descriptionCourte = "Verde-pistácio translúcido.",
            descriptionLongue = "O primeiro mineral a ser nomeado a partir de uma pessoa (o coronel Von Prehn), a prenite forma agregados botrioidais verde-pistácio a verde-amarelado, talhados em cabochão ou, ocasionalmente, a facetas quando o cristal o permite.",
            particularites = "Frequentemente talhada em cabochão; por vezes confundida com o crisoprásio.",
            inclusions = "Estrutura fibrorradiada característica que confere um aspeto ligeiramente chatoyant, por vezes com inclusões de agulhas de epídoto verde.",
            lithotherapie = "A prenite é associada à serenidade e à escuta da intuição, um apoio para a meditação."
        ),
        "chrysocolle" to GemTranslation(
            nom = "Crisocola",
            descriptionCourte = "Azul-verde cobreado, frequentemente engastado numa matriz de quartzo.",
            descriptionLongue = "Colorida pelo cobre, a crisocola raramente é suficientemente dura para ser talhada isoladamente: é mais frequentemente estabilizada numa matriz de quartzo («crisocola em quartzo»), o que lhe confere a dureza necessária para a joalharia, conservando as suas tonalidades turquesa a verde profundo.",
            particularites = "Demasiado macia em estado puro; impregnada de quartzo para uso joalheiro.",
            inclusions = "Frequentemente associada a uma silicificação parcial (crisocola em quartzo), com inclusões de cobre nativo ou de malaquite consoante o jazigo.",
            lithotherapie = "A crisocola é reputada por facilitar a expressão de si mesmo e aliviar tensões emocionais ligadas à comunicação."
        ),
        "variscite" to GemTranslation(
            nom = "Variscite",
            descriptionCourte = "Verde-maçã translúcido, prima da turquesa.",
            descriptionLongue = "Fosfato de alumínio quimicamente próximo da turquesa, a variscite apresenta um verde-maçã a verde-esmeralda veado, frequentemente atravessado por finos veios brancos de crandallite. Talhada em cabochão, mantém-se discreta no mercado.",
            particularites = "Frequentemente confundida com a turquesa; sempre talhada em cabochão.",
            lithotherapie = "A variscite é associada ao equilíbrio emocional, trazendo uma sensação de conforto e segurança interior."
        ),
        "serpentine" to GemTranslation(
            nom = "Serpentina (bowenite)",
            descriptionCourte = "Uma alternativa acessível ao jade.",
            descriptionLongue = "A bowenite, variedade compacta e dura de serpentina, é usada como substituto do jade nefrita desde a Antiguidade, na Nova Zelândia (pounamu) e na China. O seu verde translúcido e a sua tenacidade fazem dela uma pedra ornamental apreciada.",
            particularites = "A variedade bowenite, mais dura e translúcida, é a mais procurada em joalharia.",
            lithotherapie = "A serpentina é reputada por favorecer a regeneração e o enraizamento, um apoio nos períodos de reconstrução pessoal."
        ),
        "grandidierite" to GemTranslation(
            nom = "Grandidierite",
            descriptionCourte = "Uma das gemas mais raras do mundo, um azul-esverdeado pleocroico.",
            descriptionLongue = "Descoberta em Madagáscar em 1902 e nomeada em honra do explorador Alfred Grandidier, a grandidierite conta apenas com um punhado de cristais transparentes talháveis conhecidos no mundo. O seu forte pleocroísmo faz variar a cor do azul-esverdeado ao branco consoante o ângulo de observação.",
            particularites = "Menos de vinte pedras transparentes talhadas estão registadas em todo o mundo.",
            inclusions = "Espécie muito rara; as inclusões internas continuam pouco documentadas, dado que as pedras facetadas conhecidas são de pequena dimensão e apreciadas pelos colecionadores.",
            lithotherapie = "Mineral raro e precioso, a grandidierite é associada em litoterapia a uma serenidade profunda e à abertura do coração."
        ),
        "azurite" to GemTranslation(
            nom = "Azurite",
            descriptionCourte = "O azul profundo do cobre, frequentemente intercrescido com a malaquite.",
            descriptionLongue = "A azurite forma cristais e massas de um azul profundo intenso, colorida pelo cobre. Instável a longo prazo (pode transformar-se em malaquite ao contacto com a humidade), é sobretudo trabalhada em cabochão ou objeto decorativo, frequentemente associada à malaquite verde.",
            particularites = "Pode alterar-se gradualmente em malaquite (pseudomorfose); a proteger da humidade e da luz direta.",
            lithotherapie = "A azurite é reputada por estimular a intuição e a clareza mental, um apoio para a reflexão e a tomada de decisões."
        ),
        "sodalite" to GemTranslation(
            nom = "Sodalite",
            descriptionCourte = "Um azul profundo veado de branco, frequentemente confundido com o lápis-lazúli.",
            descriptionLongue = "A sodalite oferece um azul-royal veado de calcite branca, semelhante ao lápis-lazúli mas sem as inclusões douradas de pirite. Utilizada em cabochão, embutido e objetos decorativos desde a sua descoberta na Gronelândia no século XIX.",
            particularites = "Distingue-se do lápis-lazúli pela ausência de pintas douradas de pirite e por uma densidade inferior.",
            lithotherapie = "A sodalite é associada à comunicação clara e à lógica, aliviando simultaneamente a ansiedade mental."
        ),
        "larimar" to GemTranslation(
            nom = "Larimar",
            descriptionCourte = "O azul caribenho único de uma pectolite encontrada numa única ilha.",
            descriptionLongue = "O larimar é uma variedade de pectolite em azul-turquesa a azul-céu, evocando as águas das Caraíbas, cor que resulta de vestígios de cobre. Um jazigo quase único no mundo, na República Dominicana, faz dele uma gema geograficamente exclusiva.",
            particularites = "Jazigo quase exclusivo; o nome combina «Larissa» (filha do descobridor) e «mar».",
            lithotherapie = "Pedra de serenidade, o larimar é reputado por aliviar o stress e facilitar uma comunicação sincera, vinda do coração."
        ),
        "lazulite" to GemTranslation(
            nom = "Lazulite",
            descriptionCourte = "Um azul profundo a não confundir com o lápis-lazúli, apesar da semelhança do nome.",
            descriptionLongue = "A lazulite forma cristais de um azul-azure a índigo intenso, foneticamente próximo do lápis-lazúli mas sem qualquer relação química ou mineralógica. Rara em qualidade facetável, é sobretudo colecionada em espécime.",
            particularites = "A não confundir com a lazurite (componente do lápis-lazúli) apesar da proximidade dos nomes.",
            inclusions = "Inclusões fibrosas e cristais acessórios consoante o jazigo; raramente talhada devido à sua raridade em qualidade gema.",
            lithotherapie = "A lazulite é associada à introspeção e à calma mental, um apoio para a meditação e a reflexão interior."
        ),
        "hauyne" to GemTranslation(
            nom = "Haüyna",
            descriptionCourte = "Um azul-ultramar intenso encontrado em rochas vulcânicas, uma prima rara do lápis-lazúli.",
            descriptionLongue = "A haüyna, nomeada em honra do cristalógrafo René Just Haüy, apresenta um azul-ultramar profundo semelhante à lazurite do lápis-lazúli, mas surge em cristais isolados em lavas vulcânicas, sendo excecionalmente facetável.",
            particularites = "Os cristais de qualidade gema raramente ultrapassam alguns milímetros; a talha facetada é excecional.",
            inclusions = "Raras inclusões cristalinas consoante o jazigo vulcânico de origem; pedra extremamente rara em qualidade facetável.",
            lithotherapie = "A haüyna, mineral raro, é associada em litoterapia à expressão autêntica de si mesmo e à confiança na própria voz."
        ),
        "cavansite" to GemTranslation(
            nom = "Cavansite",
            descriptionCourte = "Um azul-turquesa elétrico em rosetas cristalinas, estrela dos salões mineralógicos.",
            descriptionLongue = "A cavansite forma rosetas de cristais azul-turquesa vivo revestindo geodos de basalto, apreciada acima de tudo pelos colecionadores de minerais pelo seu brilho vítreo e pela sua cor saturada, raramente talhada devido ao pequeno tamanho dos seus cristais.",
            particularites = "Quase exclusiva dos basaltos do Deccan indiano; praticamente nunca facetada.",
            inclusions = "Apresenta-se muito frequentemente em agregados esferulíticos radiados; raramente facetada como pedra individual limpa.",
            lithotherapie = "A cavansite é reputada por favorecer o despertar espiritual e a clareza de espírito nos momentos de questionamento."
        ),
        "celestite" to GemTranslation(
            nom = "Celestite",
            descriptionCourte = "Um azul pálido celeste; mineral macio sobretudo coleccionado em geodo.",
            descriptionLongue = "A celestite forma cristais tabulares de um azul pálido delicado, evocativo do céu, daí o seu nome. A sua extrema maciez reserva-a quase exclusivamente à coleção mineralógica e ao geodo decorativo, mais do que à joalharia.",
            particularites = "Demasiado macia e clivável para uso joalheiro; essencialmente uma pedra de coleção e decoração.",
            inclusions = "Frequentemente cristais prismáticos tabulares e finas inclusões líquidas; raramente facetada devido à sua fragilidade (clivagem perfeita, dureza baixa).",
            lithotherapie = "Pedra de profundo apaziguamento, a celestite é reputada por favorecer um sono sereno e acalmar pensamentos agitados."
        ),
        "euclase" to GemTranslation(
            nom = "Euclásio",
            descriptionCourte = "Um azul-esverdeado cristalino de transparência notável, notoriamente frágil.",
            descriptionLongue = "O euclásio («que cliva facilmente» em grego) tira o seu nome da sua clivagem perfeita, que o torna extremamente delicado de talhar. Os seus cristais azul-esverdeados de grande pureza são procurados pelos colecionadores de pedras facetadas raras.",
            particularites = "Clivagem perfeita numa direção: entre as gemas mais delicadas de talhar e de usar.",
            inclusions = "Inclusões líquidas frequentes e finas fraturas internas, coerentes com a sua clivagem perfeita, que torna a talha delicada.",
            lithotherapie = "O euclásio é associado à clareza de expressão e à serenidade, um apoio para comunicar com exatidão."
        ),
        "topaze-bleue" to GemTranslation(
            nom = "Topázio azul",
            descriptionCourte = "O azul profundo obtido por irradiação e aquecimento de um topázio incolor.",
            descriptionLongue = "O topázio azul natural é extremamente raro; a quase totalidade das pedras do comércio («Sky», «Swiss», «London Blue») provém de topázio incolor irradiado e depois aquecido, para desenvolver nuances de azul estáveis e duradouras.",
            particularites = "A cor é quase sempre obtida por irradiação seguida de tratamento térmico, sendo estável e permanente.",
            inclusions = "Geralmente muito limpo (frequentemente resultante do tratamento por irradiação); raras inclusões líquidas ou cristais acessórios.",
            lithotherapie = "O topázio azul é reputado por favorecer uma comunicação apaziguada e ajudar a exprimir calmamente as emoções."
        ),
        "tourmaline-bleue" to GemTranslation(
            nom = "Turmalina azul (indicolite)",
            descriptionCourte = "Um azul profundo distinto do azul-esverdeado cobreado da turmalina Paraíba.",
            descriptionLongue = "A indicolite é a variedade azul a azul-esverdeada da turmalina elbaíta, colorida pelo ferro, sem o cobre característico da Paraíba. As suas tonalidades mais escuras e abafadas fazem dela uma gema distinta, por vezes confundida com a água-marinha.",
            particularites = "Distingue-se da turmalina Paraíba pela ausência de cobre e por um tom geralmente mais escuro.",
            inclusions = "Finas tricites e tubos ocos característicos, com ocasionais inclusões cristalinas consoante o jazigo.",
            lithotherapie = "A turmalina azul (indicolite) é associada à expressão de si mesmo e ao alívio de tensões ligadas à comunicação."
        ),
        "zircon-bleu" to GemTranslation(
            nom = "Zircão azul",
            descriptionCourte = "O zircão mais procurado do mercado, um azul vivo obtido por aquecimento.",
            descriptionLongue = "O zircão azul, a cor mais comercializada da espécie, é quase sempre obtido por tratamento térmico de zircão castanho cambojano. O seu brilho adamantino e a sua forte dispersão fazem dele uma alternativa apreciada e acessível à safira azul.",
            particularites = "O tratamento térmico é quase universal e estável; forte dispersão próxima da do diamante.",
            inclusions = "Geralmente resultante de tratamento térmico; duplicado característico das arestas internas e, por vezes, finas fissuras de tensão.",
            lithotherapie = "O zircão azul é reputado por trazer calma mental e clareza, um apoio para os períodos de reflexão importante."
        ),
        "hemimorphite" to GemTranslation(
            nom = "Hemimorfite",
            descriptionCourte = "Formações botrioidais azul-esverdeadas evocativas da turquesa ou da crisocola.",
            descriptionLongue = "A hemimorfite forma agregados botrioidais azul-esverdeados frequentemente confundidos com a turquesa ou a crisocola. O seu nome («meia forma») vem dos seus cristais terem simetria diferente em cada extremidade, uma curiosidade cristalográfica.",
            particularites = "Frequentemente confundida visualmente com a crisocola ou a turquesa; a identificação exige um teste de dureza.",
            inclusions = "Apresenta-se muito frequentemente em agregados botrioidais translúcidos; estrutura fibrosa característica.",
            lithotherapie = "A hemimorfite é associada à comunicação autêntica e à cura de feridas emocionais ligadas à expressão de si mesmo."
        ),
        "shattuckite" to GemTranslation(
            nom = "Shattuckite",
            descriptionCourte = "Um azul profundo e sedoso, prima rara da crisocola.",
            descriptionLongue = "A shattuckite oferece um azul intenso e sedoso em agregados fibrosos, frequentemente encontrado junto à crisocola e à malaquite nos jazigos de cobre namibianos. Sempre trabalhada em cabochão para revelar a sua chatoyance discreta.",
            particularites = "Demasiado macia para a talha facetada; sempre moldada em cabochão.",
            lithotherapie = "A shattuckite é reputada por reforçar a intuição e facilitar uma comunicação mais consciente consigo mesmo."
        ),
        "sapphirine" to GemTranslation(
            nom = "Safirina",
            descriptionCourte = "Uma gema azul-acinzentada ultrarrara, sem qualquer parentesco com o corindo.",
            descriptionLongue = "Apesar do seu nome evocativo, a safirina não está aparentada com o corindo: é um silicato distinto, azul-acinzentado a violáceo, formado em rochas metamórficas de temperatura muito elevada, entre as gemas facetadas mais raras do mundo.",
            particularites = "Uma das gemas talhadas mais raras do mundo: apenas algumas dezenas de pedras facetadas conhecidas.",
            inclusions = "Espécie muito rara; as inclusões internas continuam pouco documentadas, dado o número muito reduzido de pedras facetadas conhecidas.",
            lithotherapie = "Mineral raro, a safirina é associada em litoterapia a uma calma profunda e à proteção emocional."
        ),
        "dumortierite" to GemTranslation(
            nom = "Dumortierite",
            descriptionCourte = "Um azul-violeta intenso em finas fibras, frequentemente incluído no quartzo.",
            descriptionLongue = "A dumortierite forma agregados fibrosos azul-violeta profundo, raramente em cristais suficientemente grandes para serem talhados isoladamente — encontra-se mais frequentemente em inclusões densas que coloram um quartzo maciço utilizado em cabochão ou contas.",
            particularites = "Frequentemente encontrada sob forma de quartzo maciço fortemente incluído de dumortierite, mais do que em cristal puro.",
            inclusions = "Apresenta-se em agregados fibrosos densos, frequentemente incluídos no quartzo (quartzo dumortierite), conferindo um efeito chatoyant azul.",
            lithotherapie = "A dumortierite é reputada por desenvolver a paciência e a disciplina mental, um apoio para aprendizagens exigentes."
        ),
        "afghanite" to GemTranslation(
            nom = "Afeganite",
            descriptionCourte = "Um azul semelhante ao lápis-lazúli, recentemente descrito, encontrado nos mesmos jazigos.",
            descriptionLongue = "Descrita cientificamente em 1968, a afeganite encontra-se nos mesmos jazigos de mármore que o lápis-lazúli afegão, partilhando uma tonalidade azul semelhante. Extremamente rara em pedra facetada, continua a ser acima de tudo uma curiosidade de coleção.",
            particularites = "Descoberta mineralógica tardia (1968); as pedras facetadas contam-se entre as mais raras do mercado.",
            inclusions = "Espécie rara associada ao lápis-lazúli afegão; pode conter finas inclusões de calcite ou pirite provenientes da rocha hospedeira.",
            lithotherapie = "A afeganite é associada a uma calma interior profunda e a uma forma suave de proteção emocional."
        ),
        "saphir-bleu" to GemTranslation(
            nom = "Safira azul",
            descriptionCourte = "O azul de referência da alta joalharia.",
            descriptionLongue = "A safira azul deve a sua cor ao ferro e ao titânio. O «azul aveludado» das pedras não tratadas da Caxemira continua a ser a referência absoluta para os conhecedores, seguido pelas proveniências da Birmânia e do Sri Lanca.",
            particularites = "Inclusões de rútilo em seda que podem produzir asterismo (safira estrelada).",
            inclusions = "Seda de rútilo fina, cristais de zircão envoltos por um halo de tensão, cristais de mica ou de feldspato, e zonamento de cor característico em bandas hexagonais, típico das pedras não aquecidas.",
            lithotherapie = "Pedra de sabedoria desde a Antiguidade, a safira azul é reputada por favorecer a clareza de espírito, a lealdade e a busca da verdade."
        ),
        "saphir-auvergne" to GemTranslation(
            nom = "Safira de Auvérnia",
            descriptionCourte = "Um corindo francês de tonalidade azul-violeta profunda, extraído dos terrenos vulcânicos de Auvérnia.",
            descriptionLongue = "Extraídas dos terrenos vulcânicos do Maciço Central, nomeadamente em torno de Espaly-Saint-Marcel, perto de Le Puy-en-Velay, as safiras de Auvérnia são uma variedade francesa de corindo com tonalidade azul-violeta profunda. Tal como as restantes safiras de origem basáltica, distinguem-se por uma cor muito intensa, mas cristais geralmente de pequeno tamanho, raramente talháveis para além de um quilate. Historicamente exploradas no século XIX, continuam hoje uma curiosidade procurada por colecionadores e amantes da gemologia francesa, mais do que uma fonte comercial de volume.",
            particularites = "Cristais geralmente pequenos (raramente mais de um quilate talhado), com a tonalidade azul-violeta muito intensa, típica das safiras de origem basáltica.",
            inclusions = "Frequentemente rica em inclusões características das safiras basálticas: cristais de plagioclase e piroxena, e zonamento de cor marcado, garantia da sua origem vulcânica francesa.",
            lithotherapie = "Tal como as restantes safiras, a safira de Auvérnia é tradicionalmente associada à sabedoria e à clareza de espírito; a sua origem francesa torna-a uma pedra particularmente apreciada pelos colecionadores ligados ao património mineralógico nacional."
        ),
        "aigue-marine" to GemTranslation(
            nom = "Água-marinha",
            descriptionCourte = "«Água do mar» cristalina.",
            descriptionLongue = "O seu nome, do latim «aqua marina», evoca a sua cor azul pálido a azul-esverdeada, lembrando a água do mar. O berilo azul distingue-se pela sua grande pureza, com muito poucas inclusões visíveis a olho nu.",
            particularites = "Frequentemente aquecida para atenuar a componente verde e intensificar o azul.",
            inclusions = "Geralmente limpa; tubos ocos paralelos ao eixo c, raras inclusões líquidas e cristais acessórios.",
            lithotherapie = "Pedra dos marinheiros, a água-marinha é tradicionalmente associada à serenidade, à coragem e a uma comunicação apaziguada, sobretudo em viagem."
        ),
        "tanzanite" to GemTranslation(
            nom = "Tanzanite",
            descriptionCourte = "Uma única fonte no mundo, aos pés do Kilimanjaro.",
            descriptionLongue = "Descoberta em 1967, a tanzanite só existe na zona de Merelani, na Tanzânia. O seu forte tricroísmo faz surgir azul, violeta e bordô consoante o ângulo de observação, antes de o aquecimento padrão estabilizar a tonalidade azul-violeta procurada.",
            particularites = "Jazigo único e em vias de esgotamento, considerada uma pedra de investimento.",
            inclusions = "Forte pleocroísmo tricroico (azul, violeta, castanho-avermelhado); ocasionais inclusões líquidas e cristais acessórios, geralmente poucos após o aquecimento.",
            lithotherapie = "A tanzanite é reputada por acompanhar a transformação interior e favorecer um despertar espiritual sereno."
        ),
        "lapis-lazuli" to GemTranslation(
            nom = "Lápis-lazúli",
            descriptionCourte = "Azul profundo salpicado de ouro, utilizado desde a Antiguidade.",
            descriptionLongue = "O lápis-lazúli é uma rocha composta sobretudo por lazurite, associada a pirite (inclusões douradas) e a calcite (veios brancos). Utilizado no Egito antigo e moído para o pigmento «azul-ultramar», adorna joias e objetos de arte há milénios.",
            particularites = "As inclusões douradas de pirite, uniformemente distribuídas, são uma garantia de qualidade.",
            lithotherapie = "Pedra de sabedoria e verdade desde o Egito antigo, o lápis-lazúli é reputado por reforçar a confiança em si mesmo e a clareza de julgamento."
        ),
        "turquoise" to GemTranslation(
            nom = "Turquesa",
            descriptionCourte = "Azul-esverdeado emblemático, veado de matriz.",
            descriptionLongue = "Utilizada desde o Egito antigo e sagrada para numerosas culturas ameríndias, a turquesa deve o seu azul ao cobre. Porosa e macia, é frequentemente estabilizada por impregnação de resina, para resistir ao uso em joalharia.",
            particularites = "Matriz veada característica; porosa, sensível a cosméticos e produtos químicos.",
            lithotherapie = "Pedra de proteção há milénios, a turquesa é reputada por favorecer a serenidade, a comunicação sincera e a proteção durante as viagens."
        ),
        "spinelle-bleu" to GemTranslation(
            nom = "Espinela azul",
            descriptionCourte = "Azul intenso, por vezes colorido por cobalto.",
            descriptionLongue = "Mais rara do que a espinela vermelha, a espinela azul deve a sua tonalidade mais apreciada a vestígios de cobalto, produzindo uma cor azul profunda e aveludada sob iluminação incandescente.",
            particularites = "Geralmente não tratada, ao contrário de muitas safiras azuis.",
            inclusions = "Cristais octaédricos acessórios e nuvens de finas inclusões, comparável às restantes espinelas naturais não tratadas.",
            lithotherapie = "A espinela azul é associada ao apaziguamento emocional e à renovação após um período de tensão."
        ),
        "paraiba-tourmaline" to GemTranslation(
            nom = "Turmalina Paraíba",
            descriptionCourte = "Azul-esverdeado «néon» elétrico, único no reino mineral.",
            descriptionLongue = "Descoberta em 1989 no estado brasileiro da Paraíba, esta turmalina deve o seu inédito azul-esverdeado elétrico a vestígios de cobre e manganês. Jazigos semelhantes foram depois encontrados em Moçambique e na Nigéria. É uma das gemas de cor mais caras do mundo.",
            particularites = "A cor «néon», causada pelo cobre, nunca é observada nas restantes turmalinas.",
            inclusions = "Geralmente de grande pureza; finas tricites e ocasionais tubos ocos, a elevada limpidez contribuindo para o valor da pedra.",
            lithotherapie = "A turmalina Paraíba é reputada por estimular uma alegria profunda e uma vitalidade renovada, em eco à sua cor radiante."
        ),
        "apatite-bleue" to GemTranslation(
            nom = "Apatite azul néon",
            descriptionCourte = "Um azul-turquesa elétrico pouco conhecido do grande público.",
            descriptionLongue = "A apatite azul néon, descoberta em Madagáscar nos anos 1990, oferece uma tonalidade turquesa muito saturada, próxima da turmalina Paraíba, a um preço bem mais acessível. A sua maciez relativa limita o seu uso a engastes protegidos.",
            particularites = "Dureza moderada (5): a reservar para brincos e pendentes, mais do que para anéis.",
            inclusions = "Inclusões líquidas frequentes e nuvens de finas partículas; pedra relativamente frágil que exige uma talha cuidada.",
            lithotherapie = "A apatite azul néon é associada à motivação e à clareza dos objetivos pessoais, um apoio para reencontrar o foco."
        ),
        "cyanite" to GemTranslation(
            nom = "Cianite (distena)",
            descriptionCourte = "Dureza que varia consoante o eixo do cristal.",
            descriptionLongue = "A cianite (ou distena, «duas resistências» em grego) é célebre pela sua dureza anisotrópica: 4,5 no sentido do comprimento do cristal, 6,5 na perpendicular. O seu azul profundo evoca por vezes a safira, a um preço bem mais acessível.",
            particularites = "A dureza anisotrópica torna a talha delicada; clivagem perfeita numa direção.",
            inclusions = "Clivagem perfeita em duas direções, frequentemente produzindo fraturas internas; finas inclusões fibrosas consoante o jazigo.",
            lithotherapie = "A cianite (distena) é reputada por favorecer o alinhamento interior e uma comunicação fluida entre o coração e a razão."
        ),
        "benitoite" to GemTranslation(
            nom = "Benitoíta",
            descriptionCourte = "A gema oficial da Califórnia, com uma dispersão notável.",
            descriptionLongue = "Descoberta em 1907 no condado de San Benito, na Califórnia, a benitoíta fluoresce em azul vivo sob UV e apresenta uma dispersão superior à do diamante. O jazigo de origem continua, mais de um século depois, a ser praticamente a única fonte de qualidade gema no mundo.",
            particularites = "Fluorescência azul viva sob UV; um jazigo de qualidade gema quase único no mundo.",
            inclusions = "Extremamente rara; pode apresentar finas inclusões líquidas, mantendo-se a maioria das pedras facetadas de tamanho muito reduzido.",
            lithotherapie = "Mineral raro e precioso, a benitoíta é associada em litoterapia à elevação espiritual e à clareza de consciência."
        ),
        "jeremejevite" to GemTranslation(
            nom = "Jeremejevite",
            descriptionCourte = "Um borato de alumínio de raridade extrema, azul pálido a incolor.",
            descriptionLongue = "Descrita em 1883 na Sibéria e durante muito tempo impossível de encontrar em qualidade gema, a jeremejevite só foi redescoberta em quantidade explorável na Namíbia nos anos 1970. O seu azul pálido límpido e a sua raridade fazem dela uma pedra de coleção apreciada pelos conhecedores.",
            particularites = "O essencial da produção gema mundial provém de um único maciço namibiano.",
            inclusions = "Espécie muito rara; as inclusões internas continuam pouco documentadas, dado o número limitado de pedras facetáveis em qualidade gema (sobretudo na Namíbia).",
            lithotherapie = "A jeremejevite, extremamente rara, é associada à abertura de espírito e à ligação a uma forma de sabedoria superior."
        ),
        "violane" to GemTranslation(
            nom = "Violana",
            descriptionCourte = "Uma variedade maciça e compacta do diópsido, azul-violeta profundo.",
            descriptionLongue = "A violana é uma variedade maciça e compacta de diópsido, de um azul-violeta intenso próximo do de certas azuritas, colorida por inclusões de magnetite. Sempre trabalhada em cabochão ou objeto polido.",
            particularites = "O seu jazigo tipo e histórico é o Vale de Aosta, em Itália; sempre moldada em cabochão.",
            lithotherapie = "A violana, variedade violeta de diópsido, é associada ao apaziguamento mental e à introspeção, um apoio para a meditação."
        ),
        "saphir-violet" to GemTranslation(
            nom = "Safira violeta",
            descriptionCourte = "Um violeta profundo, na fronteira entre a safira azul e o rubi.",
            descriptionLongue = "A safira violeta deve a sua tonalidade a uma mistura de vestígios de ferro, titânio e crómio, situando-se na fronteira cromática entre a safira azul e o rubi. Algumas pedras apresentam uma mudança de cor parcial consoante a iluminação.",
            particularites = "Pode apresentar uma ligeira mudança de cor entre a luz do dia e a luz incandescente.",
            inclusions = "Zonamento de cor sectorial, seda de rútilo e inclusões cristalinas semelhantes às das restantes variedades de corindo.",
            lithotherapie = "A safira violeta é reputada por favorecer a espiritualidade e a intuição, um apoio para os períodos de questionamento interior."
        ),
        "purpurite" to GemTranslation(
            nom = "Purpurite",
            descriptionCourte = "Um violeta-vermelho opaco intenso, rara pedra ornamental de fosfato.",
            descriptionLongue = "A purpurite deve o seu nome à sua cor púrpura intensa, resultado da alteração de fosfatos de manganês e ferro. Opaca e relativamente macia, é moldada em cabochão para joalharia e objetos de arte.",
            particularites = "A cor de superfície pode desvanecer-se com a exposição prolongada à luz; a proteger.",
            lithotherapie = "A purpurite é associada à transformação pessoal e à força interior nos períodos de mudança."
        ),
        "hackmanite" to GemTranslation(
            nom = "Hackmanite",
            descriptionCourte = "Uma pedra camaleão que fica rosada sob UV e depois desvanece à luz do dia.",
            descriptionLongue = "A hackmanite é uma variedade tenebrescente de sodalite: exposta aos UV, desenvolve uma tonalidade rosa-violeta que se atenua depois progressivamente à luz do dia, um fenómeno reversível fascinante e único entre as gemas.",
            particularites = "Um fenómeno de tenebrescência reversível: a cor varia consoante a exposição recente aos UV ou à luz.",
            inclusions = "Distingue-se pela tenebrescência (mudança de cor reversível à luz); inclusões cristalinas variáveis consoante o jazigo afegão ou gronelandês.",
            lithotherapie = "A hackmanite é reputada por estimular a intuição e oferecer uma forma de proteção energética, sobretudo durante a meditação."
        ),
        "lepidolite" to GemTranslation(
            nom = "Lepidolite",
            descriptionCourte = "A mica lilás ao lítio, frequentemente associada à turmalina rosa.",
            descriptionLongue = "A lepidolite é uma mica rica em lítio, com uma tonalidade lilás a malva característica, frequentemente encontrada em pegmatito junto à turmalina rosa e à kunzita, com as quais partilha a mesma química de lítio.",
            particularites = "Demasiado macia e laminada para a joalharia facetada; utilizada em cabochão, contas e objetos decorativos.",
            lithotherapie = "Rica em lítio natural, a lepidolite é tradicionalmente reputada por acalmar o stress e a ansiedade e favorecer um sono tranquilo."
        ),
        "stichtite" to GemTranslation(
            nom = "Stichtite",
            descriptionCourte = "Um lilás violeta-rosado, frequentemente entrelaçado com serpentina verde (atlantasite).",
            descriptionLongue = "A stichtite forma massas lilás violeta-rosadas, frequentemente intercrescidas com serpentina verde para formar a «atlantasite», uma combinação muito procurada para cabochões e objetos ornamentais.",
            particularites = "Extremamente macia: reservada a cabochões e peças decorativas pouco expostas a choques.",
            inclusions = "Apresenta-se geralmente em agregados fibrosos translúcidos, frequentemente associados à serpentina.",
            lithotherapie = "A stichtite é associada à compaixão para consigo mesmo e para com os outros, favorecendo o perdão e o apaziguamento emocional."
        ),
        "amethyste" to GemTranslation(
            nom = "Ametista",
            descriptionCourte = "A pedra da temperança.",
            descriptionLongue = "A ametista deve a sua cor violeta a vestígios de ferro combinados com irradiação natural. Abundante e acessível, foi ainda assim usada pela nobreza e pelo clero durante séculos, símbolo de sobriedade e espiritualidade.",
            particularites = "Pode desbotar sob exposição prolongada à luz solar.",
            inclusions = "Zonamento de cor em chevron (maclas do Brasil), véus de finas inclusões líquidas, por vezes cristais fantasma de crescimento.",
            lithotherapie = "A ametista é uma das pedras mais reputadas em litoterapia para acalmar o stress, favorecer um sono sereno e apoiar a meditação e a espiritualidade."
        ),
        "spinelle-violet" to GemTranslation(
            nom = "Espinela violeta",
            descriptionCourte = "Tenacidade e brilho para uma alternativa durável.",
            descriptionLongue = "A espinela violeta combina uma boa dureza com a ausência de clivagem, o que a torna uma alternativa muito resistente à ametista ou à safira violeta, com um brilho vítreo particularmente vivo.",
            particularites = "Geralmente não tratada.",
            inclusions = "Pequenos cristais octaédricos e finas inclusões nebulosas típicas da espécie, não tratada por natureza.",
            lithotherapie = "A espinela violeta é associada à renovação espiritual e à serenidade interior."
        ),
        "iolite" to GemTranslation(
            nom = "Iolite",
            descriptionCourte = "A «safira dos vikings».",
            descriptionLongue = "A iolite tira o seu nome do grego «ios» (violeta). O seu pleocroísmo impressionante faz variar a cor do azul-violeta ao amarelo pálido quase incolor, consoante o ângulo de observação, uma particularidade que os navegadores vikings terão usado para se orientar.",
            particularites = "Pleocroísmo tricroico muito marcado, determinante para a orientação da talha.",
            inclusions = "Inclusões de hematite em finas plaquetas orientadas, responsáveis por um efeito chatoyant apelidado de «bloodshot iolite» em certos jazigos.",
            lithotherapie = "Utilizada pelos navegadores vikings para se orientar, a iolite é reputada por reforçar a intuição e a clareza visionária nas escolhas de vida."
        ),
        "grenat-rhodolite-violet" to GemTranslation(
            nom = "Granada rodolita violácea",
            descriptionCourte = "Uma tonalidade púrpura que muda consoante a iluminação.",
            descriptionLongue = "Certas rodolitas apresentam uma dominante púrpura-violeta particularmente marcada sob luz natural, oferecendo uma alternativa acessível às pedras violetas mais raras.",
            particularites = "Cor estável, nunca tratada.",
            inclusions = "Cristais acessórios ocasionais e finas fibrilas internas, comparáveis às da rodolita clássica.",
            lithotherapie = "Esta variedade violácea de rodolita é associada ao equilíbrio entre a paixão e a serenidade emocional."
        ),
        "sugilite" to GemTranslation(
            nom = "Sugilite",
            descriptionCourte = "Violeta intenso, popularizado nos anos 1970.",
            descriptionLongue = "Descrita no Japão em 1944 e depois popularizada pelos jazigos sul-africanos descobertos nos anos 1970, a sugilite oferece um violeta a púrpura profundo, opaco a translúcido, talhado em cabochão.",
            particularites = "Sempre talhada em cabochão; o principal jazigo sul-africano está hoje esgotado.",
            lithotherapie = "A sugilite é reputada por oferecer proteção espiritual e conforto nos períodos de luto ou de grande fadiga emocional."
        ),
        "charoite" to GemTranslation(
            nom = "Charoíta",
            descriptionCourte = "Um único jazigo na Sibéria.",
            descriptionLongue = "Descrita apenas em 1978, a charoíta só é conhecida de um único jazigo à beira do rio Chara, na Sibéria. O seu motivo turbilhonante violeta e branco, devido ao entrelaçamento de fibras cristalinas, faz dela uma pedra ornamental imediatamente reconhecível.",
            particularites = "O único jazigo do género no mundo; um motivo turbilhonante característico, sempre talhada em cabochão.",
            inclusions = "Estrutura fibrorradiada densa e característica, atravessada por veios de manganês negro (aegirina) e, por vezes, de calcite branca.",
            lithotherapie = "A charoíta é associada a uma transformação interior profunda e à coragem necessária para enfrentar a mudança."
        ),
        "taaffeite" to GemTranslation(
            nom = "Taaffeíta",
            descriptionCourte = "O primeiro mineral descoberto numa pedra já talhada.",
            descriptionLongue = "Identificada em 1945 pelo gemólogo Richard Taaffe numa pedra já facetada e classificada erradamente como espinela, a taaffeíta continua a ser uma das gemas mais raras do mundo, em tonalidades malva a lilás delicadas.",
            particularites = "Longamente confundida com a espinela; distingue-se por uma dupla refração que a espinela não possui.",
            inclusions = "Espécie extremamente rara, longamente confundida com a espinela; as inclusões internas continuam pouco documentadas.",
            lithotherapie = "Mineral extremamente raro, a taaffeíta é associada em litoterapia ao despertar de consciência e à singularidade do caminho pessoal."
        ),
        "axinite" to GemTranslation(
            nom = "Axinite",
            descriptionCourte = "Cristais em lâmina de machado, forte pleocroísmo.",
            descriptionLongue = "O seu nome vem do grego «axine» (machado), em referência à forma aguda e achatada dos seus cristais. A axinite apresenta um forte pleocroísmo castanho-violeta a amarelo-esverdeado consoante o ângulo de observação, apreciada pelos colecionadores de pedras raras.",
            particularites = "Pleocroísmo tricroico marcado; cristais historicamente descritos primeiro em França (Dauphiné).",
            inclusions = "Finas inclusões líquidas e cristais acessórios consoante o jazigo; pedra de forte pleocroísmo, facetada com precisão para revelar a sua cor.",
            lithotherapie = "A axinite é reputada por favorecer o enraizamento e a concentração, oferecendo um apoio para permanecer centrado nos períodos agitados."
        ),
        "cobaltocalcite" to GemTranslation(
            nom = "Cobaltocalcite",
            descriptionCourte = "Um rosa-doce vivo, variedade de calcite colorida pelo cobalto.",
            descriptionLongue = "A cobaltocalcite (calcite cobaltífera) apresenta um rosa vivo elétrico devido a vestígios de cobalto, formando crostas botrioidais muito apreciadas pelos colecionadores. A sua maciez extrema exclui qualquer uso joalheiro corrente.",
            particularites = "Extremamente macia e sensível a ácidos como toda a calcite; pedra de coleção exclusivamente.",
            lithotherapie = "A cobaltocalcite é associada ao amor-próprio e à ternura, um doce apoio emocional nos períodos sensíveis."
        ),
        "thulite" to GemTranslation(
            nom = "Tulite",
            descriptionCourte = "A variedade rosa da zoisite, prima da tanzanite azul.",
            descriptionLongue = "A tulite é a variedade rosa a vermelho-rosada da zoisite, colorida pelo manganês — o mesmo mineral que a tanzanite, mas sem o aquecimento que revela o azul-violeta desta última. Descoberta na Noruega, deve-lhe o seu nome (Thule).",
            particularites = "Quase sempre opaca e moldada em cabochão; as pedras facetadas transparentes são raras.",
            lithotherapie = "A tulite é reputada por reavivar a alegria e a vitalidade afetiva, um apoio para reencontrar as emoções positivas."
        ),
        "rhodonite" to GemTranslation(
            nom = "Rodonite",
            descriptionCourte = "Um rosa profundo veado de negro manganesífero.",
            descriptionLongue = "A rodonite oferece um rosa a vermelho-rosado intenso, atravessado por veios negros de óxidos de manganês que lhe conferem um aspeto marmoreado característico. Pedra nacional da Rússia, adorna historicamente os palácios imperiais.",
            particularites = "Pedra nacional da Rússia; os veios negros de manganês formam um motivo de identificação característico.",
            lithotherapie = "A rodonite é tradicionalmente associada ao perdão e à cura de feridas afetivas, sobretudo após uma rutura."
        ),
        "topaze-rose" to GemTranslation(
            nom = "Topázio rosa",
            descriptionCourte = "A cor natural mais rara do topázio, historicamente extraído no Paquistão.",
            descriptionLongue = "O topázio rosa natural e não tratado é bem mais raro do que o topázio azul ou incolor. O jazigo histórico de Katlang, no Paquistão, forneceu algumas das mais belas pedras, com uma tonalidade rosa-pêssego delicada.",
            particularites = "O rosa natural não tratado é raro; distinto do topázio rosa obtido por tratamento térmico de pedras castanhas.",
            inclusions = "Ocasionais inclusões líquidas e finas fraturas internas; geralmente boa pureza.",
            lithotherapie = "O topázio rosa é reputado por favorecer a doçura nas relações e abrir o coração ao amor sincero."
        ),
        "quartz-rose" to GemTranslation(
            nom = "Quartzo rosa",
            descriptionCourte = "O quartzo rosa-pastel, pedra do amor em todas as tradições.",
            descriptionLongue = "O quartzo rosa, colorido por vestígios de titânio, manganês ou por microscópicas inclusões fibrosas de dumortierite, é associado ao amor e à ternura na maioria das culturas. Os cristais transparentes facetáveis são raros; o material maciço translúcido é bem mais comum.",
            particularites = "Algumas pedras apresentam um asterismo de seis raios (quartzo rosa estrelado) talhado em cabochão.",
            inclusions = "Frequentemente ligeiramente enevoado devido a finas inclusões fibrosas de dumortierite; pode apresentar um efeito asteriado quando talhado em cabochão.",
            lithotherapie = "A pedra do amor incondicional por excelência, o quartzo rosa é reputado por aliviar as feridas do coração e favorecer a ternura para consigo mesmo e para com os outros."
        ),
        "phosphosiderite" to GemTranslation(
            nom = "Fosfosiderite",
            descriptionCourte = "Um rosa-violeta suave em crostas mameladas, prima da variscite.",
            descriptionLongue = "A fosfosiderite forma crostas mameladas rosa-lilás a violáceas, quimicamente próxima da variscite verde mas colorida pelo ferro. Sempre trabalhada em cabochão para revelar a sua chatoyance sedosa.",
            particularites = "Dureza próxima da variscite; sempre moldada em cabochão.",
            inclusions = "Estrutura fibrorradiada densa com brilho sedoso, raramente facetada devido à sua translucidez limitada.",
            lithotherapie = "A fosfosiderite é associada ao desapego e à suavidade interior, um apoio durante a meditação."
        ),
        "morganite" to GemTranslation(
            nom = "Morganita",
            descriptionCourte = "Rosa suave a pêssego, nomeada em 1911.",
            descriptionLongue = "Batizada em honra do financeiro e colecionador J.P. Morgan pelo gemólogo George Kunz, a morganita oferece uma tonalidade rosa a pêssego delicada devido ao manganês. Muito pura, é frequentemente talhada em pedras grandes e espetaculares.",
            particularites = "Frequentemente aquecida para atenuar uma componente alaranjada e revelar um rosa puro.",
            inclusions = "Tubos de alongamento paralelos ao eixo c e ocasionais inclusões líquidas; geralmente muito limpa.",
            lithotherapie = "A morganita é reputada por abrir o coração à compaixão e ao amor-próprio, aliviando a ansiedade afetiva."
        ),
        "kunzite" to GemTranslation(
            nom = "Kunzita",
            descriptionCourte = "Pleocroísmo marcado, pedra delicada.",
            descriptionLongue = "Descoberta em 1902 e nomeada em honra do gemólogo George Frederick Kunz, a kunzita apresenta um rosa-lilás sedutor. É, contudo, sensível à luz prolongada e a choques térmicos, sendo aconselhável um uso ocasional.",
            particularites = "Clivagem nítida em duas direções; a proteger da luz direta prolongada.",
            inclusions = "Finas inclusões líquidas e clivagem perfeita em duas direções que tornam a talha delicada; pedra sensível a choques.",
            lithotherapie = "A kunzita é associada ao amor incondicional e a uma cura emocional profunda, um apoio para libertar tensões acumuladas."
        ),
        "saphir-rose" to GemTranslation(
            nom = "Safira rosa",
            descriptionCourte = "Na fronteira entre o rubi e a safira.",
            descriptionLongue = "Colorida pelo crómio como o rubi, mas em concentração menor, a safira rosa situa-se no limite convencional com o rubi: além de uma certa saturação, a pedra é reclassificada como rubi.",
            particularites = "O limite entre o rubi e a safira rosa continua debatido entre laboratórios gemológicos.",
            inclusions = "Seda de rútilo fina, cristais de zircão com halos de tensão e zonamento de cor em bandas, comparáveis aos do rubi, a mesma espécie.",
            lithotherapie = "A safira rosa é reputada por favorecer o amor sincero e a harmonia nas relações afetivas."
        ),
        "tourmaline-rose" to GemTranslation(
            nom = "Turmalina rosa",
            descriptionCourte = "Manganês para uma tonalidade suave.",
            descriptionLongue = "Menos saturada do que a rubelite, a turmalina rosa oferece tonalidades suaves, do rosa pálido ao rosa-doce, frequentemente associadas aos cristais bicolores ou tricolores característicos do grupo.",
            particularites = "Os cristais são frequentemente zonados, dando origem a turmalinas bicolores.",
            inclusions = "Tricites em fios de algodão e tubos ocos típicos da espécie, por vezes com inclusões cristalinas de mica.",
            lithotherapie = "A turmalina rosa é associada à ternura e à cura de feridas emocionais ligadas ao amor e ao apego."
        ),
        "rhodochrosite" to GemTranslation(
            nom = "Rodocrosite",
            descriptionCourte = "Bandas concêntricas rosa e branco.",
            descriptionLongue = "Reconhecível pelos seus motivos concêntricos rosa e branco, evocativos de anéis de árvore, a rodocrosite é uma pedra decorativa e de coleção apreciada, mas demasiado frágil para uso diário num anel.",
            particularites = "Muito frágil e sensível a ácidos; reservada a peças de coleção ou pendentes protegidos.",
            lithotherapie = "A rodocrosite é reputada por favorecer o amor-próprio e a cura da criança interior, um apoio no trabalho emocional profundo."
        ),
        "saphir-blanc" to GemTranslation(
            nom = "Safira branca",
            descriptionCourte = "Corindo sem vestígios corantes, uma alternativa discreta ao diamante.",
            descriptionLongue = "Desprovida dos vestígios metálicos que coloram o rubi ou a safira azul, a safira branca (ou «leucossafira») oferece um brilho próximo do diamante a um preço bem mais baixo, longamente utilizada como pedra de substituição em relojoaria e joalharia.",
            particularites = "Dispersão inferior à do diamante, mas dureza quase igual; excelente resistência ao uso quotidiano.",
            inclusions = "Geralmente muito limpa a olho nu; pode apresentar um ligeiro zonamento de crescimento e raros cristais minerais acessórios.",
            lithotherapie = "A safira branca é reputada por favorecer a clareza de espírito e a pureza de intenção nas decisões importantes."
        ),
        "topaze-blanche" to GemTranslation(
            nom = "Topázio branco",
            descriptionCourte = "O topázio na sua forma mais pura e mais comum, incolor e límpido.",
            descriptionLongue = "O topázio incolor é, na realidade, a cor mais difundida da espécie na natureza — os topázios azuis do comércio são, aliás, quase sempre obtidos a partir dele por tratamento. Límpido e brilhante, serve também de substituto económico do diamante.",
            particularites = "A principal matéria-prima utilizada para produzir o topázio azul tratado por irradiação.",
            inclusions = "Regra geral, uma pedra muito limpa; poucas inclusões visíveis a olho nu.",
            lithotherapie = "O topázio branco é associado à clareza mental e à busca da verdade nas escolhas de vida."
        ),
        "hambergite" to GemTranslation(
            nom = "Hambergite",
            descriptionCourte = "Uma gema incolor de extrema raridade, tão frágil quanto brilhante.",
            descriptionLongue = "A hambergite é uma gema incolor apenas ligeiramente tingida, rara e brilhante, mas de uma fragilidade extrema devido a uma clivagem perfeita que a torna um desafio formidável para os lapidários — uma das pedras mais raramente vistas no mercado.",
            particularites = "A clivagem perfeita torna tanto a talha como o uso em joia particularmente arriscados; pedra de coleção.",
            inclusions = "Espécie rara com clivagem perfeita; as inclusões internas continuam pouco documentadas, dado o reduzido número de pedras de qualidade gema.",
            lithotherapie = "Mineral raro, a hambergite é associada em litoterapia à clareza mental e à concentração."
        ),
        "petalite" to GemTranslation(
            nom = "Petalite",
            descriptionCourte = "Um minério de lítio raramente facetado, discreto e límpido.",
            descriptionLongue = "A petalite, importante fonte de lítio industrial, produz ocasionalmente cristais gema incolores a ligeiramente tingidos, talhados para colecionadores mais do que para a joalharia do grande público.",
            particularites = "Extraída acima de tudo como minério de lítio; as qualidades gema facetáveis são anedóticas.",
            inclusions = "Geralmente muito limpa; pode apresentar finas inclusões líquidas e clivagem perfeita, tornando a talha delicada.",
            lithotherapie = "A petalite é reputada por favorecer uma serenidade profunda, particularmente apreciada como companheira de meditação."
        ),
        "phenakite" to GemTranslation(
            nom = "Fenacite",
            descriptionCourte = "Uma gema incolor tão límpida que foi longamente confundida com o quartzo ou o diamante.",
            descriptionLongue = "O nome da fenacite (do grego «impostor») vem da sua semelhança enganadora com o quartzo ou até o diamante em bruto. Rara e de belo brilho quando facetada, continua a ser sobretudo apreciada pelos colecionadores experientes.",
            particularites = "O seu nome grego significa «impostor», em referência à confusão histórica com o quartzo.",
            inclusions = "Frequentemente de grande pureza; raras inclusões líquidas ou cristais acessórios consoante o jazigo.",
            lithotherapie = "A fenacite é associada ao despertar de consciência e a uma grande clareza espiritual, reservada às práticas meditativas avançadas."
        ),
        "bytownite" to GemTranslation(
            nom = "Bytownite",
            descriptionCourte = "Um feldspato raramente facetável, polo cálcico da série dos plagioclases.",
            descriptionLongue = "A bytownite, rica em cálcio no seio da série dos plagioclases (entre a labradorite e a anortite), forma excecionalmente cristais límpidos suficientemente puros para serem facetados, principalmente no Congo e na Índia.",
            particularites = "O membro cálcico da série dos plagioclases, entre a labradorite e a anortite pura.",
            inclusions = "Pode apresentar finas lamelas de exsolução e inclusões de cobre na origem de um efeito chatoyant em certas pedras próximas da labradorite.",
            lithotherapie = "A bytownite é reputada por oferecer um enraizamento luminoso, entre a proteção suave e a clareza de espírito."
        ),
        "hyalite" to GemTranslation(
            nom = "Hialite",
            descriptionCourte = "Uma opala incolor e transparente que brilha em verde fluorescente sob UV.",
            descriptionLongue = "A hialite é uma opala não preciosa, incolor e perfeitamente transparente em finas camadas, célebre pela sua fluorescência verde vivo sob luz ultravioleta, devida a vestígios de urânio — um espetáculo apreciado pelos entusiastas de minerais fluorescentes.",
            particularites = "Fluorescência verde viva sob UV devida a vestígios de urânio, sem o jogo de cores da opala preciosa.",
            inclusions = "Variedade de opala geralmente incolor e muito limpa, por vezes fluorescente sob UV devido a vestígios de urânio.",
            lithotherapie = "Esta variedade de opala incolor é associada à pureza e à leveza de espírito."
        ),
        "anhydrite" to GemTranslation(
            nom = "Anidrite",
            descriptionCourte = "Sulfato de cálcio sem água, prima seca do gesso, raramente talhada.",
            descriptionLongue = "A anidrite, quimicamente próxima do gesso mas desprovida de água de cristalização, ocorre em tonalidades incolores a azul pálido ou violáceas. A sua maciez e a sua clivagem reservam-na a um uso confidencial de coleção.",
            particularites = "Hidrata-se lentamente em gesso ao contacto prolongado com água, um fenómeno natural de transformação mineral.",
            inclusions = "Cristais frequentemente clivados em lâminas e finas inclusões líquidas; raramente facetada devido à sua fragilidade.",
            lithotherapie = "A anidrite é reputada por trazer estrutura e clareza à organização dos pensamentos e do quotidiano."
        ),
        "baryte" to GemTranslation(
            nom = "Barite",
            descriptionCourte = "Um mineral denso e macio, raramente facetado mas espetacular em cristal.",
            descriptionLongue = "A barite (sulfato de bário) deve o seu nome à sua densidade notável para um mineral não metálico. Os seus cristais tabulares, frequentemente incolores a amarelo-mel, são ocasionalmente facetados para colecionadores, apesar da sua grande fragilidade.",
            particularites = "Densidade excecionalmente elevada para um mineral não metálico, usada como critério de identificação.",
            inclusions = "Cristais tabulares frequentemente incluindo finas partículas coloridas consoante o jazigo; raramente facetada devido à sua fragilidade.",
            lithotherapie = "A barite é associada ao enraizamento e à estabilidade emocional, um apoio nos períodos de mudança."
        ),
        "aragonite" to GemTranslation(
            nom = "Aragonite",
            descriptionCourte = "O polimorfo do calcário que também forma as pérolas e o coral.",
            descriptionLongue = "A aragonite é o polimorfo ortorrômbico do carbonato de cálcio — a mesma substância que compõe as pérolas, as conchas e o coral. Os seus cristais terrestres, frequentemente incolores a amarelo pálido, são sobretudo colecionados em estado bruto.",
            particularites = "Instável a muito longo prazo: converte-se lentamente em calcite, o seu polimorfo mais estável.",
            inclusions = "Estrutura frequentemente maclada em pseudo-hexágonos característicos, com finas inclusões líquidas.",
            lithotherapie = "A aragonite é reputada por favorecer o enraizamento e a paciência, ajudando a aceitar o ritmo natural das coisas."
        ),
        "calcite" to GemTranslation(
            nom = "Calcite",
            descriptionCourte = "O mineral mais comum da crosta terrestre, ocasionalmente facetado.",
            descriptionLongue = "A calcite é um dos minerais mais difundidos do mundo, apresentando uma extraordinária diversidade de formas cristalinas. Demasiado macia para uso diário, é ainda assim facetada por colecionadores pela sua espetacular birrefringência (o duplicado da imagem através da pedra).",
            particularites = "Birrefringência extrema: um objeto visto através de um cristal de calcite límpido surge duplicado.",
            inclusions = "Forte birrefringência que provoca um nítido duplicado das arestas internas, visível a olho nu; clivagem perfeita em três direções.",
            lithotherapie = "A calcite é tradicionalmente utilizada para purificar as energias envolventes e trazer clareza mental."
        ),
        "cerusite" to GemTranslation(
            nom = "Cerussite",
            descriptionCourte = "Um minério de chumbo com uma dispersão espetacular, rara em pedra facetada.",
            descriptionLongue = "A cerussite, minério de chumbo, possui uma dispersão ótica superior à do diamante, produzindo fogos notáveis uma vez facetada. A sua densidade muito elevada e a sua grande fragilidade fazem dela uma gema exclusivamente de coleção.",
            particularites = "Dispersão ótica superior à do diamante; densidade muito elevada, característica do chumbo.",
            inclusions = "Forte brilho adamantino e elevada dispersão; maclas frequentes em estrela de seis raios, pedra delicada de talhar.",
            lithotherapie = "A cerussite é associada ao enraizamento e a uma transformação interior suave."
        ),
        "montebrasite" to GemTranslation(
            nom = "Montebrasite",
            descriptionCourte = "Uma gema discreta ao lítio, prima da ambligonite.",
            descriptionLongue = "A montebrasite, prima próxima da ambligonite, da qual apenas se distingue pelo seu teor em hidroxilo, oferece pedras incolores a amarelo pálido, facetadas acima de tudo para os entusiastas de raridades litiníferas.",
            particularites = "O seu jazigo tipo e homónimo situa-se em Montebras, na Creuse, França, descoberto no século XIX.",
            inclusions = "Ocasionais inclusões líquidas, próxima da ambligonite, de que é a variedade rica em hidroxilo.",
            lithotherapie = "A montebrasite é reputada por favorecer a clareza de espírito e o discernimento face a escolhas importantes."
        ),
        "diamant" to GemTranslation(
            nom = "Diamante",
            descriptionCourte = "A gema mais dura conhecida.",
            descriptionLongue = "Formado sob temperatura e pressão muito elevadas no manto terrestre, o diamante é composto por carbono puro cristalizado. A sua dureza máxima, a sua forte dispersão (o «fogo») e o seu brilho adamantino fazem dele a pedra de referência da alta joalharia, avaliada segundo os «4C»: carat (quilate), colour (cor), clarity (pureza) e cut (talha).",
            particularites = "A única gema com dureza 10; certificação obrigatória (GIA, HRD...) para pedras importantes.",
            inclusions = "Cristais de minerais profundos (granada, olivina), nuvens de finas partículas, «penas» (fraturas), pontos negros de carbono e linhas de crescimento; as inclusões caracterizam a pureza segundo a escala GIA.",
            lithotherapie = "Símbolo de força e pureza desde sempre, o diamante é reputado por amplificar as energias envolventes e reforçar a clareza de intenção e a confiança em si mesmo."
        ),
        "zircon-blanc" to GemTranslation(
            nom = "Zircão branco",
            descriptionCourte = "Forte dispersão, longamente utilizado como substituto do diamante.",
            descriptionLongue = "A não confundir com a zircónia cúbica (material sintético), o zircão é uma gema natural cuja forte dispersão luminosa rivaliza com a do diamante, o que fez dele um substituto histórico apreciado.",
            particularites = "Frequentemente aquecido para obter o incolor a partir de zircão castanho; as arestas das facetas surgem por vezes duplicadas.",
            inclusions = "Forte birrefringência que provoca um duplicado visível das arestas facetadas traseiras; geralmente limpo após o tratamento térmico.",
            lithotherapie = "O zircão branco é associado à clareza de espírito e à pureza de intenção, uma alternativa luminosa ao diamante."
        ),
        "goshenite" to GemTranslation(
            nom = "Goshenite (berilo branco)",
            descriptionCourte = "A rara variedade incolor do berilo.",
            descriptionLongue = "Menos procurada comercialmente do que as suas primas coloridas (esmeralda, água-marinha, morganita), a goshenite é, contudo, a forma mais pura do berilo, totalmente desprovida de elementos cromogénicos.",
            particularites = "Servia historicamente para fabricar lentes de óculos antes do uso do vidro ótico.",
            inclusions = "O berilo mais límpido da família; ocasionais tubos ocos, muito poucas inclusões visíveis.",
            lithotherapie = "A goshenite (berilo incolor) é reputada por favorecer a clareza mental e ajudar a ver as situações com objetividade."
        ),
        "cristal-de-roche" to GemTranslation(
            nom = "Cristal de rocha",
            descriptionCourte = "Quartzo puro, transparente e abundante.",
            descriptionLongue = "Totalmente incolor no seu estado puro, o cristal de rocha é uma das gemas mais abundantes na Terra. Foi longamente utilizado para talhar esferas de adivinhação e óticas, antes da era do vidro industrial.",
            particularites = "Grande disponibilidade em cristais grandes, permitindo talhas de fantasia espetaculares.",
            inclusions = "Geralmente totalmente limpo; pode conter inclusões minerais decorativas (rútilo, turmalina, clorite) ou cristais negativos.",
            lithotherapie = "Pedra «mestra» da litoterapia, o cristal de rocha é reputado por amplificar as energias, clarificar os pensamentos e purificar o espaço envolvente."
        ),
        "danburite" to GemTranslation(
            nom = "Danburite",
            descriptionCourte = "Um brilho próximo do topázio, pouco conhecida.",
            descriptionLongue = "Descoberta em Danbury (Connecticut) no século XIX, a danburite assemelha-se muito ao topázio incolor ou amarelo pálido, mas sem a sua clivagem perfeita, o que a torna mais fácil de talhar e de usar no dia a dia.",
            particularites = "Nenhuma clivagem, ao contrário do topázio, que frequentemente imita visualmente.",
            inclusions = "Geralmente muito limpa; raras inclusões líquidas ou cristais acessórios consoante o jazigo birmanês ou mexicano.",
            lithotherapie = "A danburite é associada a uma grande serenidade e ao despertar do coração, um apoio suave para a meditação."
        ),
        "bois-fossilise" to GemTranslation(
            nom = "Madeira fossilizada",
            descriptionCourte = "A madeira da árvore substituída átomo a átomo por sílica, ao longo de milhões de anos.",
            descriptionLongue = "A madeira fossilizada resulta da silicificação progressiva de troncos de árvores soterrados, o quartzo substituindo a matéria orgânica ao mesmo tempo que conserva a estrutura lenhosa original, anéis de crescimento incluídos. Uma vez polida, revela motivos naturais impressionantes.",
            particularites = "Conserva fielmente a estrutura celular original da madeira, por vezes visível ao microscópio.",
            lithotherapie = "A madeira fossilizada é reputada por oferecer um enraizamento profundo e recordar a paciência necessária a toda a transformação duradoura."
        ),
        "os-fossilise" to GemTranslation(
            nom = "Osso fossilizado",
            descriptionCourte = "Ossos, por vezes de dinossauros, mineralizados e polidos em cabochão.",
            descriptionLongue = "O osso fossilizado, por vezes proveniente de verdadeiros ossos de dinossauro, mineraliza-se pela substituição da apatite orgânica por sílica ou outros minerais, conservando a estrutura porosa característica do tecido ósseo, revelada uma vez polida.",
            particularites = "A estrutura celular porosa original permanece visível uma vez a pedra polida, assinatura do tecido ósseo fóssil.",
            lithotherapie = "Associado ao enraizamento e à estabilidade, o osso fossilizado recordaria a importância das raízes e da memória pessoal."
        ),
        "kornerupine" to GemTranslation(
            nom = "Kornerupina",
            descriptionCourte = "Uma gema rara verde-castanha com forte pleocroísmo, por vezes com mudança de cor.",
            descriptionLongue = "A kornerupina apresenta um pleocroísmo pronunciado (várias cores visíveis consoante o ângulo de observação, do verde ao castanho-avermelhado), e certas pedras do Sri Lanca apresentam mesmo uma mudança de cor comparável à da alexandrita.",
            particularites = "Pleocroísmo tricroico pronunciado, por vezes acompanhado de uma mudança de cor consoante a fonte luminosa.",
            inclusions = "Forte pleocroísmo acompanhado de finas inclusões fibrosas que podem produzir um efeito chatoyant em algumas pedras.",
            lithotherapie = "A kornerupina, mineral discreto e raro, é associada a um enraizamento suave e à estabilidade interior."
        ),
        "hyperstene" to GemTranslation(
            nom = "Hiperstena",
            descriptionCourte = "Um castanho-bronze chatoyant, por vezes chamado «pedra de veludo».",
            descriptionLongue = "A hiperstena apresenta uma cintilação bronze-dourada característica (schiller) devida a inclusões lamelares internas, o que lhe vale o apelido de «pedra de veludo». É mais frequentemente talhada em cabochão para revelar este efeito.",
            particularites = "O efeito de cintilação bronze-dourada (schiller) deve-se a lamelas de exsolução internas.",
            lithotherapie = "A hiperstena é reputada por favorecer a introspeção e oferecer uma discreta forma de proteção energética."
        ),
        "paesine" to GemTranslation(
            nom = "Paesina",
            descriptionCourte = "Uma rocha calcária cujos motivos naturais evocam paisagens em miniatura.",
            descriptionLongue = "A paesina, ou «pietra paesina» (pedra paisagem), é uma rocha calcária em que infiltrações de óxidos de ferro e manganês desenham naturalmente motivos evocativos de paisagens, ruínas ou horizontes — um fenómeno pictórico inteiramente natural, apreciado na Toscana desde o Renascimento.",
            particularites = "Cada placa polida é única, como uma pintura natural formada pela capilaridade de óxidos metálicos.",
            lithotherapie = "Apelidada de «pedra paisagem», a paesina convida à contemplação e a uma calma interior profunda."
        ),
        "enstatite" to GemTranslation(
            nom = "Enstatite",
            descriptionCourte = "Uma piroxena castanho-esverdeada, ocasionalmente com asterismo ou efeito olho-de-gato.",
            descriptionLongue = "A enstatite, membro extremo magnesiano puro das ortopiroxenas, ocorre em tons castanho-esverdeados a oliva, ocasionalmente com um asterismo de quatro raios ou um efeito olho-de-gato quando talhada em cabochão.",
            particularites = "Pode apresentar um asterismo de quatro raios, mais raro do que o asterismo clássico de seis raios do corindo.",
            inclusions = "Pode apresentar finas inclusões fibrosas orientadas, produzindo um efeito chatoyant em cabochão.",
            lithotherapie = "A enstatite é associada ao enraizamento e a uma capacidade de ação ponderada e refletida."
        ),
        "sphalerite" to GemTranslation(
            nom = "Esfalerite",
            descriptionCourte = "O minério de zinco com a dispersão mais elevada de todas as gemas facetadas.",
            descriptionLongue = "A esfalerite, principal minério de zinco, possui uma dispersão ótica recorde entre as gemas facetadas — superior à do diamante — produzindo fogos espetaculares. A sua maciez extrema faz dela uma pedra de coleção mais do que de uso diário.",
            particularites = "A dispersão mais elevada entre todas as gemas comummente coleccionadas, superando a do diamante.",
            inclusions = "Dispersão muito elevada e brilho adamantino; clivagem perfeita em seis direções torna-a uma pedra delicada de talhar, com raras inclusões líquidas.",
            lithotherapie = "A esfalerite é reputada por favorecer o enraizamento energético, estimulando simultaneamente a vitalidade física."
        ),
        "rutile" to GemTranslation(
            nom = "Rútilo",
            descriptionCourte = "O cristal responsável pelas inclusões douradas do quartzo rutilado, raramente facetado isoladamente.",
            descriptionLongue = "O rútilo, óxido de titânio de brilho metálico, é sobretudo conhecido como mineral incluído no quartzo rutilado, mas encontra-se excecionalmente em cristais suficientemente puros e transparentes para serem facetados, revelando uma dispersão muito elevada.",
            particularites = "Dispersão ótica muito elevada, próxima da do diamante, raramente explorada devido à sua cor escura.",
            lithotherapie = "O rútilo é tradicionalmente associado à amplificação das energias e à clareza na prossecução dos objetivos."
        ),
        "quartz-fume" to GemTranslation(
            nom = "Quartzo fumado",
            descriptionCourte = "Castanho translúcido, colorido por irradiação natural.",
            descriptionLongue = "O quartzo fumado deve a sua cor castanha a centros de cor induzidos pela radioatividade natural da rocha encaixante, atuando sobre vestígios de alumínio. Abundante e acessível, é frequentemente aquecido para ser transformado em citrino.",
            particularites = "Pode ser aquecido para virar amarelo (citrino) ou desbotar sob exposição prolongada à luz.",
            inclusions = "Véus de finas inclusões líquidas e ocasionais cristais negativos, comparável ao cristal de rocha.",
            lithotherapie = "O quartzo fumado é reputado pelas suas poderosas virtudes de enraizamento, ajudando a absorver o stress e as tensões do quotidiano."
        ),
        "andalousite" to GemTranslation(
            nom = "Andaluzita",
            descriptionCourte = "Pleocroísmo espetacular verde-castanho-vermelho.",
            descriptionLongue = "A andaluzita deve o seu nome à região espanhola onde foi descrita pela primeira vez. O seu forte pleocroísmo tricroico faz surgir, consoante o ângulo, tonalidades verde-oliva, castanho-vermelho e amarelo numa mesma pedra, um efeito por vezes apelidado de «alexandrita do pobre».",
            particularites = "Pleocroísmo tricroico muito marcado, tornando a orientação da talha determinante.",
            inclusions = "Forte pleocroísmo visível a olho nu (verde, castanho, vermelho consoante o ângulo); inclusões de grafite por vezes dispostas em cruz (variedade chiastolite).",
            lithotherapie = "A andaluzita é associada ao enraizamento e à capacidade de mudar de perspetiva perante as dificuldades."
        ),
        "sinhalite" to GemTranslation(
            nom = "Sinhalite",
            descriptionCourte = "Longamente confundida com o peridoto castanho.",
            descriptionLongue = "Identificada como espécie distinta apenas em 1952, a sinhalite havia sido anteriormente classificada por erro entre os peridotos castanhos nas coleções de museus. O seu nome vem de «Sinhala», o antigo nome do Sri Lanca, a sua principal fonte.",
            particularites = "Confundida com o peridoto até 1952; sempre castanha, nunca verde, ao contrário do peridoto.",
            inclusions = "Finas inclusões líquidas e cristais acessórios consoante o jazigo do Sri Lanca; historicamente confundida durante muito tempo com o peridoto.",
            lithotherapie = "A sinhalite, mineral raro e discreto, é associada à estabilidade interior e à perseverança."
        ),
        "staurotide" to GemTranslation(
            nom = "Estaurolite (pedra de cruz)",
            descriptionCourte = "Célebre pelas suas maclas em cruz.",
            descriptionLongue = "A estaurolite forma naturalmente maclas cruciformes conhecidas como «pedras de cruz» ou «pedras de fada», tradicionalmente usadas como amuleto. Raramente facetada devido à sua opacidade frequente, é sobretudo colecionada em estado de macla bruta.",
            particularites = "Maclas cruciformes características; raramente facetada, sobretudo colecionada em bruto.",
            lithotherapie = "Apelidada de pedra de cruz, a estaurolite é tradicionalmente usada como talismã de proteção e sorte."
        ),
        "sphene" to GemTranslation(
            nom = "Esfeno (titanite)",
            descriptionCourte = "A dispersão mais elevada depois de um punhado de gemas extremamente raras.",
            descriptionLongue = "O esfeno apresenta uma dispersão ótica (o «fogo») superior à do diamante, associada a um forte pleocroísmo castanho-verde-amarelo. A sua maciez relativa faz dele uma pedra reservada sobretudo à coleção e a joias pouco expostas a choques.",
            particularites = "Dispersão excecional, superior à do diamante; bastante macia e clivável.",
            inclusions = "Dispersão muito elevada («fogo»), frequentemente superior à do diamante; nuvens de finas inclusões e cristais acessórios frequentes.",
            lithotherapie = "O esfeno (titanite) é reputado por estimular a clareza mental e a criatividade, um apoio para projetos que exigem precisão e inspiração."
        ),
        "hematite" to GemTranslation(
            nom = "Hematite",
            descriptionCourte = "O óxido de ferro metálico cinzento-negro, polido em espelho desde a Antiguidade.",
            descriptionLongue = "A hematite é talhada em cabochão ou entalhe para revelar um brilho metálico cinzento-negro quase de espelho. Utilizada como pedra de selo desde o Egito antigo, o seu pó dá, aliás, um traço vermelho característico — origem do seu nome, do grego «sangue».",
            particularites = "O seu pó (traço) é vermelho-sangue apesar da sua aparência metálica negra, origem do seu nome grego.",
            lithotherapie = "Pedra de enraizamento por excelência, a hematite é reputada por reforçar a força interior e proteger das energias negativas envolventes."
        ),
        "magnetite" to GemTranslation(
            nom = "Magnetite",
            descriptionCourte = "O íman natural da Antiguidade, conhecido pelo nome de pedra-ímã.",
            descriptionLongue = "A magnetite é o mineral naturalmente magnético por excelência, conhecido desde a Antiguidade como «pedra-ímã». Raramente facetada devido à sua opacidade total, é sobretudo trabalhada em contas e cabochões.",
            particularites = "O único mineral naturalmente e fortemente magnético, propriedade utilizada desde a Antiguidade para a navegação.",
            lithotherapie = "A magnetite é associada ao enraizamento e ao equilíbrio energético, frequentemente utilizada para recentrar o corpo e o espírito."
        ),
        "quartz-tourmaline" to GemTranslation(
            nom = "Quartzo turmalinado",
            descriptionCourte = "Agulhas de turmalina negra congeladas num quartzo límpido.",
            descriptionLongue = "O quartzo turmalinado aprisiona agulhas de turmalina negra (xorlo) num cristal de quartzo por outro lado límpido, criando um motivo gráfico impressionante muito apreciado tanto em litoterapia como em joalharia contemporânea.",
            particularites = "As agulhas de turmalina permanecem visíveis a olho nu, criando um motivo gráfico único em cada pedra.",
            inclusions = "Agulhas de turmalina negra (xorlo) entrelaçadas num quartzo límpido.",
            lithotherapie = "O quartzo turmalinado associa as virtudes protetoras da turmalina negra à clareza amplificadora do cristal de rocha."
        ),
        "onyx" to GemTranslation(
            nom = "Ónix",
            descriptionCourte = "Bandas negras e brancas, frequentemente tingidas.",
            descriptionLongue = "Variedade microcristalina de quartzo da família das calcedónias, o ónix apresenta naturalmente bandas negras e brancas. A maioria das pedras comercializadas é tingida para obter um negro uniforme e intenso.",
            particularites = "A tinturagem artificial é quase universal, para homogeneizar a cor.",
            lithotherapie = "O ónix é tradicionalmente associado à força interior, à estabilidade emocional e a uma proteção suave no quotidiano."
        ),
        "spinelle-noir" to GemTranslation(
            nom = "Espinela negra",
            descriptionCourte = "Brilho metálico para a joalharia masculina.",
            descriptionLongue = "Opaca e de um negro profundo, a espinela negra é particularmente apreciada na joalharia masculina contemporânea pelo seu brilho quase metálico e pela sua robustez ao uso quotidiano.",
            particularites = "Elevada resistência a riscos, adequada a joias usadas diariamente.",
            lithotherapie = "A espinela negra é reputada por oferecer uma proteção energética sólida, favorecendo simultaneamente o enraizamento."
        ),
        "tourmaline-noire" to GemTranslation(
            nom = "Turmalina negra (Xorlo)",
            descriptionCourte = "A variedade de turmalina mais comum.",
            descriptionLongue = "Rico em ferro, o xorlo é, de longe, a variedade de turmalina mais difundida na Terra. Opaco e de um negro-azeviche, é tradicionalmente associado a virtudes protetoras em litoterapia.",
            particularites = "Cristais prismáticos frequentemente estriados, por vezes de grande dimensão.",
            lithotherapie = "A turmalina negra (xorlo) é uma das pedras de proteção mais reputadas em litoterapia, tida como capaz de absorver energias negativas e reforçar o enraizamento."
        ),
        "obsidienne" to GemTranslation(
            nom = "Obsidiana",
            descriptionCourte = "Vidro natural de fratura extremamente afiada.",
            descriptionLongue = "Formada pelo arrefecimento rápido de lava rica em sílica, a obsidiana é um vidro vulcânico amorfo. A sua fratura conchoidal extremamente afiada fez dela uma ferramenta de eleição desde a Pré-História, nomeadamente para pontas de flecha e lâminas.",
            particularites = "Algumas variedades apresentam um brilho dourado ou iridescente (obsidiana arco-íris).",
            lithotherapie = "A obsidiana é reputada por oferecer uma proteção poderosa, revelando ao mesmo tempo verdades ocultas, favorecendo uma transformação interior profunda."
        ),
        "rubis-etoile" to GemTranslation(
            nom = "Rubi estrelado",
            descriptionCourte = "Uma estrela de seis pontas que desliza pela superfície do cabochão.",
            descriptionLongue = "O rubi estrelado deve o seu asterismo a finas inclusões de rútilo em agulhas («seda»), orientadas segundo a simetria hexagonal do corindo, que refletem a luz numa estrela de seis pontas móvel quando a pedra é talhada em cabochão.",
            particularites = "O asterismo só é visível em talha de cabochão, nunca em talha facetada; exige uma fonte de luz pontual.",
            inclusions = "Deve o seu asterismo a uma densa rede de seda de rútilo orientada segundo os três eixos do cristal; a densidade e a orientação desta seda condicionam a nitidez da estrela de seis pontas.",
            lithotherapie = "O rubi estrelado conjuga as virtudes protetoras do rubi com um poder de guia interior simbolizado pela sua estrela."
        ),
        "saphir-etoile" to GemTranslation(
            nom = "Safira estrelada",
            descriptionCourte = "Uma estrela luminosa de seis pontas, frequentemente numa safira azul ou negra.",
            descriptionLongue = "Tal como a sua prima o rubi estrelado, a safira estrelada deve o seu asterismo a inclusões de rútilo em seda. Encontra-se mais frequentemente em azul ou em negro, sendo esta última tradicionalmente associada à proteção em várias culturas asiáticas.",
            particularites = "O asterismo mais procurado apresenta seis raios perfeitamente retos e centrados na cúpula do cabochão.",
            inclusions = "Uma densa rede de seda de rútilo orientada segundo os três eixos do corindo, produzindo o asterismo de seis raios visível em cabochão.",
            lithotherapie = "A safira estrelada é reputada por trazer orientação e proteção espiritual, simbolizando a sua estrela um caminho a seguir."
        ),
        "saphir-teal" to GemTranslation(
            nom = "Safira teal",
            descriptionCourte = "Um corindo bicolor onde o azul e o amarelo se combinam numa tonalidade azul-esverdeada distinta.",
            descriptionLongue = "A safira teal deve a sua tonalidade azul-esverdeada característica à coexistência, num mesmo cristal, de zonas de crescimento azuis (ferro e titânio) e amarelas (ferro), que se fundem visualmente uma vez a pedra talhada. Esta bicoloração natural, mais do que uma tonalidade uniforme, faz dela uma pedra muito procurada pelos colecionadores de cores atípicas, sobretudo nos jazigos do Montana.",
            particularites = "A bicoloração azul-amarela, visível em zonas distintas em bruto, funde-se numa tonalidade azul-esverdeada homogénea uma vez a pedra talhada e orientada.",
            inclusions = "Zonamento de cor azul-esverdeado característico em bandas, seda de rútilo discreta, cristais acessórios típicos do corindo australiano.",
            lithotherapie = "A safira teal é reputada por favorecer o equilíbrio entre a razão e a intuição, a sua dupla coloração simbolizando a harmonia entre duas energias complementares."
        ),
        "diaspore-zultanite" to GemTranslation(
            nom = "Zultanite",
            descriptionCourte = "Uma mudança de cor do verde-caqui ao rosa-champanhe, um único jazigo na Turquia.",
            descriptionLongue = "Comercializada sob o nome de «zultanite», esta variedade de diásporo muda de cor do verde-caqui oliva sob luz do dia para o rosa-champanhe a violáceo sob luz incandescente, proveniente de um único jazigo nas montanhas turcas.",
            particularites = "Um jazigo quase único no mundo; a mudança de cor é mais subtil do que a da alexandrita.",
            inclusions = "Forte pleocroísmo (verde, amarelo, rosa-champanhe consoante a iluminação); finas inclusões líquidas e clivagem perfeita, tornando a talha delicada.",
            lithotherapie = "A zultanite, que muda de cor com a luz, é associada à adaptabilidade e à capacidade de transformação pessoal."
        ),
        "ametrine" to GemTranslation(
            nom = "Ametrina",
            descriptionCourte = "Um quartzo bicolor onde o violeta da ametista e o amarelo do citrino partilham um mesmo cristal.",
            descriptionLongue = "A ametrina deve a sua bicoloração a um gradiente natural de temperatura no interior do cristal de quartzo durante o seu crescimento: as zonas mais aquecidas assumiram a tonalidade amarela do citrino, enquanto as zonas mais frias conservaram o violeta da ametista. A mina boliviana de Anahí, longamente a única fonte comercial no mundo, está associada a uma lenda do século XVII que atribui a sua descoberta a um conquistador espanhol que casou com uma princesa local proprietária do jazigo.",
            particularites = "A talha é pensada para sublinhar o contraste nítido entre as duas zonas de cor, frequentemente dispostas segundo uma diagonal.",
            inclusions = "Zonamento nítido entre os setores violeta e amarelo herdado da estrutura cristalina do quartzo, com as inclusões líquidas típicas da espécie.",
            lithotherapie = "A ametrina é reputada por conjugar as virtudes apaziguadoras da ametista com as virtudes estimulantes do citrino, um equilíbrio entre calma interior e energia criativa."
        ),
        "grenat-couleur-changeante" to GemTranslation(
            nom = "Granada com mudança de cor",
            descriptionCourte = "Verde-azulada de dia, vermelho-violeta ao entardecer, uma rival pouco conhecida da alexandrita.",
            descriptionLongue = "Certas granadas piropo-espessartite da África Oriental apresentam uma espetacular mudança de cor, do verde-azulado ou verde-acinzentado sob luz do dia ao vermelho-violeta sob luz incandescente, um fenómeno raro entre as granadas.",
            particularites = "O vanádio, mais do que o crómio, é responsável pela mudança de cor nesta granada.",
            inclusions = "Cristais acessórios e finas fibras típicas da granada piropo-espessartite, cuja composição intermédia partilha.",
            lithotherapie = "Esta granada de mudança de cor simboliza a adaptabilidade e a capacidade de se renovar perante circunstâncias em mudança."
        ),
        "pietersite" to GemTranslation(
            nom = "Pietersite",
            descriptionCourte = "Um turbilhão azul-dourado chatoyant, apelidado de «olho da tempestade».",
            descriptionLongue = "A pietersite é um quartzo com inclusões fibrosas de crocidolite fraturadas e recimentadas, produzindo uma chatoyance caótica azul, dourada e castanha, evocativa de uma tempestade congelada — daí o seu apelido de «olho da tempestade». Descoberta na Namíbia em 1962.",
            particularites = "O motivo chatoyant caótico, ao contrário do padrão regular do olho-de-tigre, resulta de uma fraturação natural das fibras internas.",
            lithotherapie = "Apelidada de «pedra da tempestade», a pietersite é reputada por apoiar a coragem perante mudanças rápidas e imprevistas."
        ),
        "agate" to GemTranslation(
            nom = "Ágata",
            descriptionCourte = "O bandado concêntrico colorido mais emblemático do quartzo.",
            descriptionLongue = "A ágata é uma calcedónia que apresenta bandas concêntricas ou paralelas de cores variadas, formadas por depósitos sucessivos de sílica em cavidades vulcânicas. As suas inúmeras variedades (musgo, dendrítica, paisagem, olho...) fazem dela uma das pedras ornamentais mais coleccionadas do mundo.",
            particularites = "O bandado é frequentemente realçado por tinturagem, uma prática antiga e amplamente aceite pelo mercado.",
            lithotherapie = "A ágata é tradicionalmente associada ao equilíbrio emocional, à estabilidade e a uma proteção suave no quotidiano."
        ),
        "jaspe" to GemTranslation(
            nom = "Jaspe",
            descriptionCourte = "Um quartzo opaco de motivos infinitos, do vermelho-sangue ao verde-paisagem.",
            descriptionLongue = "O jaspe é um agregado microcristalino de quartzo tornado opaco por numerosas impurezas minerais, oferecendo uma paleta de cores e motivos quase ilimitada. O «jaspe paisagem» imita cenas naturais inteiras na pedra polida.",
            particularites = "Opacidade total ao contrário da ágata, devida à densidade das impurezas minerais incluídas.",
            lithotherapie = "O jaspe é reputado por favorecer o enraizamento e a resistência, um apoio para se manter firme nos períodos exigentes."
        ),
        "calcedoine" to GemTranslation(
            nom = "Calcedónia",
            descriptionCourte = "A forma microcristalina do quartzo, base da ágata, da cornalina e do ónix.",
            descriptionLongue = "A calcedónia é a forma criptocristalina do quartzo (microcristais invisíveis a olho nu), da qual derivam a ágata, a cornalina, o crisoprásio e o ónix. A variedade azul-acinzentada translúcida, dita «calcedónia azul», é a mais procurada em joalharia.",
            particularites = "Um termo genérico que designa o quartzo microcristalino; a ágata, a cornalina e o ónix são variedades suas com nome próprio.",
            inclusions = "Estrutura microcristalina fibrosa responsável pela sua translucidez leitosa; poucas inclusões visíveis a olho nu.",
            lithotherapie = "A calcedónia é associada à harmonia interior e a uma comunicação apaziguada com os outros."
        ),
        "quartz-a-inclusions" to GemTranslation(
            nom = "Quartzo com inclusões (jardim)",
            descriptionCourte = "Uma paisagem mineral em miniatura congelada num cristal límpido.",
            descriptionLongue = "Numerosas variedades de quartzo límpido contêm inclusões de outros minerais — clorite, actinolite, hematite, rútilo, litiofilite, fuchsite ou pirite consoante os jazigos — criando paisagens internas únicas apelidadas de «quartzo jardim» (lodolite) ou quartzo fantasma.",
            particularites = "Cada pedra é única consoante a natureza do mineral incluído; nunca há dois quartzos com inclusões idênticos.",
            inclusions = "Contém, por definição, inclusões minerais variadas e abundantes — clorite, actinolite, hematite, rútilo, litiofilite ou fuchsite consoante o jazigo — criando paisagens internas únicas («jardim»).",
            lithotherapie = "O quartzo com inclusões (dito «jardim») convida à introspeção, simbolizando cada inclusão uma faceta do mundo interior."
        ),
        "quartz-rutile" to GemTranslation(
            nom = "Quartzo rutilado",
            descriptionCourte = "«Cabelos de Vénus» dourados congelados num cristal de rocha límpido.",
            descriptionLongue = "O quartzo rutilado aprisiona finas agulhas douradas de rútilo, poeticamente apelidadas de «cabelos de Vénus» ou «flechas de Cupido», criando um efeito decorativo impressionante muito procurado em joalharia contemporânea.",
            particularites = "As inclusões de rútilo podem também produzir um efeito olho-de-gato quando o cristal é talhado em cabochão.",
            inclusions = "Agulhas de rútilo douradas ou acobreadas atravessando o cristal, por vezes dispostas em feixes ou em estrela.",
            lithotherapie = "O quartzo rutilado associa as virtudes amplificadoras do cristal de rocha a um poder protetor reforçado."
        ),
        "quartz-super-sept" to GemTranslation(
            nom = "Quartzo super sete",
            descriptionCourte = "Até sete minerais reunidos num único cristal de ametista brasileira.",
            descriptionLongue = "O «Super Seven» (ou melody stone) é um quartzo ametistado do Brasil que contém até sete minerais distintos como inclusões — cacoxenite, goetite, lepidocrocite, rútilo, hematite, entre outros — criando motivos dourados e violáceos únicos em cada pedra.",
            particularites = "Um jazigo único no mundo; o nome comercial refere-se aos sete minerais que podem estar presentes.",
            inclusions = "Uma associação característica de sete minerais incluídos (ametista, cacoxenite, rútilo, goetite, lepidocrocite, limonite, hematite), única no jazigo brasileiro da Baía.",
            lithotherapie = "Rara combinação de sete minerais, o quartzo super sete é reputado por favorecer uma meditação profunda e uma forma de síntese espiritual."
        ),
        "smithsonite" to GemTranslation(
            nom = "Smithsonite",
            descriptionCourte = "Protuberâncias botrioidais «rebuçado» numa vasta paleta pastel.",
            descriptionLongue = "A smithsonite forma massas botrioidais numa vasta gama de cores pastel — rosa, azul, verde, amarelo ou malva consoante os vestígios metálicos presentes — com uma superfície sedosa e arredondada evocativa de rebuçados, muito apreciada em cabochão.",
            particularites = "A cor varia consoante o metal em vestígio presente: cobre (azul-esverdeado), cobalto (rosa), cádmio (amarelo).",
            inclusions = "Apresenta-se muito frequentemente em agregados botrioidais translúcidos em tonalidades pastel; estrutura interna finamente granulada.",
            lithotherapie = "A smithsonite é associada à suavidade e ao apaziguamento emocional, um apoio para acalmar a irritabilidade."
        ),
        "moldavite" to GemTranslation(
            nom = "Moldavite",
            descriptionCourte = "Um vidro verde-oliva nascido do impacto de um meteorito há 15 milhões de anos.",
            descriptionLongue = "A moldavite é um vidro natural formado pela fusão instantânea de rocha terrestre durante o impacto de um meteorito na Baviera, há cerca de 15 milhões de anos, que projetou gotículas de vidro fundido até à Boémia, onde é hoje encontrada.",
            particularites = "Um jazigo geograficamente único no mundo, ligado à cratera de impacto de Ries, na Baviera (Alemanha).",
            inclusions = "Vidro natural de origem meteorítica, contendo tipicamente bolhas de gás alongadas e filamentos de sílica fundida (lechatelierite).",
            lithotherapie = "De origem meteorítica, a moldavite é reputada por desencadear uma transformação interior intensa e um despertar espiritual acelerado."
        ),
        "verre-libyque" to GemTranslation(
            nom = "Vidro líbico",
            descriptionCourte = "Um vidro amarelo translúcido do deserto, presente na joia peitoral de Tutankhamon.",
            descriptionLongue = "O vidro líbico é um vidro natural amarelo pálido a amarelo-esverdeado, formado há 29 milhões de anos no deserto da Líbia por um impacto meteorítico ou uma explosão aérea. Um escaravelho talhado neste vidro adorna o peitoral funerário de Tutankhamon.",
            particularites = "Utilizado por artesãos egípcios antigos há mais de 3000 anos, muito antes da sua descrição científica moderna.",
            inclusions = "Vidro natural de origem meteorítica/tectite, contendo bolhas de gás e, por vezes, finas inclusões de zircão ou baddeleyite.",
            lithotherapie = "Formado por um impacto meteorítico há milhões de anos, o vidro líbico é associado à clareza de espírito e a uma proteção solar simbólica."
        ),
        "alexandrite" to GemTranslation(
            nom = "Alexandrita",
            descriptionCourte = "Verde de dia, vermelha sob luz incandescente.",
            descriptionLongue = "Descoberta nos Urais no século XIX e nomeada em honra do futuro czar Alexandre II, a alexandrita muda de cor de forma espetacular: verde-esmeralda à luz do dia, vermelho-púrpura sob iluminação incandescente. As pedras que apresentam uma mudança de cor marcada são extremamente raras e procuradas.",
            particularites = "A percentagem de mudança de cor é o principal critério de valorização.",
            inclusions = "Finas inclusões líquidas e cristais acessórios; podem ocorrer maclas cíclicas formando uma estrela de três raios, tal como no crisoberilo clássico.",
            lithotherapie = "A alexandrita, que muda de cor com a luz, é reputada por favorecer a adaptabilidade e o equilíbrio entre razão e intuição."
        ),
        "tourmaline-pasteque" to GemTranslation(
            nom = "Turmalina melancia",
            descriptionCourte = "Coração rosa cercado de verde, como uma fatia de fruta.",
            descriptionLongue = "Resultado de um crescimento cristalino em várias etapas químicas, a turmalina melancia apresenta um núcleo rosa rodeado por uma camada verde, talhada em fatias finas para revelar este motivo natural impressionante.",
            particularites = "Mais frequentemente talhada em cortes transversais para revelar o efeito «melancia».",
            inclusions = "Zonamento de cor nítido entre um núcleo rosa e um bordo verde, com as tricites e tubos ocos típicos da turmalina.",
            lithotherapie = "A turmalina melancia associa as virtudes apaziguadoras do rosa à energia protetora do verde, simbolizando o equilíbrio entre coração e ação."
        ),
        "labradorite" to GemTranslation(
            nom = "Labradorite",
            descriptionCourte = "Reflexos metálicos móveis (labradorescência).",
            descriptionLongue = "A labradorite apresenta um fenómeno ótico chamado labradorescência: reflexos azul-esverdeados, por vezes dourados ou violáceos, surgem e desaparecem consoante o ângulo de observação, devidos a lamelas internas que difratam a luz.",
            particularites = "A orientação da talha é determinante para revelar a labradorescência.",
            inclusions = "Lamelas de exsolução responsáveis pelo seu brilho iridescente (labradorescência), por vezes acompanhadas de finas inclusões de ilmenite ou magnetite.",
            lithotherapie = "A labradorite é reputada por oferecer uma forte proteção energética, estimulando simultaneamente a intuição e a magia do quotidiano."
        ),
        "pierre-de-lune" to GemTranslation(
            nom = "Pedra da lua",
            descriptionCourte = "Um brilho azulado flutuante (adularescência).",
            descriptionLongue = "A pedra da lua deve o seu nome ao seu brilho azulado flutuante, a adularescência, causada pelo intercrescimento de dois feldspatos à escala microscópica, que difratam a luz. As melhores qualidades de azul vivo provêm do Sri Lanca.",
            particularites = "Adularescência ótima quando a pedra é talhada em cabochão perpendicularmente às lamelas internas.",
            inclusions = "Lamelas de exsolução albite-ortóclase responsáveis pela adularescência, esse brilho azulado que parece flutuar sob a superfície.",
            lithotherapie = "A pedra da lua é tradicionalmente associada à intuição, à sensibilidade e a novos começos, em ligação com os ciclos lunares."
        ),
        "pierre-de-soleil" to GemTranslation(
            nom = "Pedra do sol",
            descriptionCourte = "Uma cintilação acobreada devida a inclusões de cobre.",
            descriptionLongue = "Ao contrário da pedra da lua, a pedra do sol deve a sua cintilação quente (aventurescência) a finas plaquetas de cobre ou hematite incluídas no cristal, produzindo reflexos laranja a vermelho-cobre consoante a iluminação.",
            particularites = "Aventurescência devida a plaquetas de cobre nativo, ao contrário do quartzo aventurina, colorido pela fuchsite.",
            inclusions = "Plaquetas de hematite ou goetite, inclusões planas e orientadas, responsáveis pela cintilação característica (aventurescência).",
            lithotherapie = "A pedra do sol é reputada por trazer alegria de viver, vitalidade e confiança em si mesmo, à imagem do seu brilho caloroso."
        ),
        "fluorine" to GemTranslation(
            nom = "Fluorite",
            descriptionCourte = "A paleta de cores mais vasta do reino mineral.",
            descriptionLongue = "A fluorite pode apresentar-se em quase todas as cores, por vezes várias num mesmo cristal zonado. A sua maciez e a sua clivagem perfeita em quatro direções limitam o seu uso em joalharia, mas fazem dela uma pedra de coleção extremamente apreciada.",
            particularites = "Clivagem perfeita em quatro direções; fluorescência característica sob UV, na origem do termo «fluorescência».",
            inclusions = "Por vezes zonamento de cor em bandas visível, finas inclusões líquidas; a clivagem perfeita em quatro direções torna-a uma pedra frágil para uso em joalharia.",
            lithotherapie = "A fluorite é muito utilizada para favorecer a concentração e a clareza mental, nomeadamente durante períodos de estudo ou trabalho intenso."
        ),
        "ammolite" to GemTranslation(
            nom = "Amolite",
            descriptionCourte = "A iridescência congelada de conchas de amonites fossilizadas.",
            descriptionLongue = "A amolite provém do nácar fossilizado de conchas de amonites com 70 milhões de anos, encontradas quase exclusivamente ao longo das Montanhas Rochosas canadianas. Apresenta uma iridescência multicolor comparável à da opala, única entre as gemas orgânicas.",
            particularites = "Uma gema orgânica fóssil; um quase-monopólio geográfico no sul de Alberta.",
            lithotherapie = "A amolite, gema orgânica fóssil, é associada à sorte, à vitalidade e à transformação positiva."
        ),
        "corail" to GemTranslation(
            nom = "Coral vermelho",
            descriptionCourte = "O esqueleto calcário de um animal marinho, vermelho-sangue precioso desde a Antiguidade.",
            descriptionLongue = "O coral vermelho precioso é o esqueleto calcário ramificado de um pequeno animal marinho colonial (Corallium rubrum), colhido no Mediterrâneo desde a Antiguidade. A sua sobre-exploração fez dele uma gema orgânica hoje estritamente regulamentada.",
            particularites = "A colheita é estritamente regulamentada (CITES para certas espécies) devido à sobre-exploração histórica dos recifes.",
            lithotherapie = "O coral vermelho é tradicionalmente usado como proteção, sobretudo para crianças, e associado à vitalidade e à energia familiar."
        ),
        "perle-conque" to GemTranslation(
            nom = "Pérola de búzio (Lambi)",
            descriptionCourte = "Uma pérola rosa-chama sem nácar, proveniente do búzio caribenho.",
            descriptionLongue = "A pérola de búzio, ou pérola Lambi, forma-se no búzio-rainha (Strombus gigas) das Caraíbas. Ao contrário das pérolas nacaradas clássicas, é não nacarada e deve o seu brilho sedoso e o seu motivo «chama» característico à estrutura fibrosa da aragonite.",
            particularites = "Uma estrutura «chama» visível à superfície, única das pérolas não nacaradas, como a pérola de búzio ou a pérola de melo.",
            lithotherapie = "A pérola de búzio é associada à feminilidade, à intuição e à suavidade emocional."
        ),
        "ambre" to GemTranslation(
            nom = "Âmbar",
            descriptionCourte = "Resina de árvore fossilizada ao longo de milhões de anos.",
            descriptionLongue = "O âmbar é resina de coníferas ou de árvores com flor fossilizada ao longo de milhões de anos. A sua leveza característica e as suas inclusões por vezes espetaculares (insetos, matéria vegetal) fizeram dele um material precioso desde a Pré-História, nomeadamente ao longo da «rota do âmbar» báltica.",
            particularites = "Flutua em água salgada; pode conter inclusões fósseis (insetos, matéria vegetal) muito procuradas.",
            inclusions = "Pode conter inclusões fósseis espetaculares — insetos, matéria vegetal, bolhas de ar —, verdadeiras janelas sobre ecossistemas antigos, particularmente apreciadas na rota báltica.",
            lithotherapie = "O âmbar é reputado desde a Antiguidade pelas suas virtudes apaziguadoras e protetoras, trazendo calor e conforto emocional."
        ),
        "perle" to GemTranslation(
            nom = "Pérola de cultura",
            descriptionCourte = "A única gema produzida por um ser vivo.",
            descriptionLongue = "Formada por um molusco em reação a um corpo estranho, a pérola é constituída por camadas concêntricas de nácar. A quase totalidade das pérolas comercializadas hoje são pérolas de cultura (Akoya, Taiti, Mares do Sul), limitando-se a intervenção humana à implantação do núcleo inicial.",
            particularites = "Preço avaliado à peça ou ao fio, consoante o tamanho, a forma, o brilho e a origem, não ao quilate.",
            inclusions = "Estrutura de nácar em camadas concêntricas por vezes visível por transparência nas pérolas finas; irregularidades de crescimento próprias de cada pérola, garantia da sua autenticidade natural ou de cultura.",
            lithotherapie = "A pérola de cultura é associada à pureza, à sabedoria e à harmonia nas relações afetivas."
        ),
        "aventurine" to GemTranslation(
            nom = "Aventurina verde",
            descriptionCourte = "Um quartzo verde cintilante, salpicado de pintas de fuchsite.",
            descriptionLongue = "A aventurina deve o seu nome e a sua cintilação característica (aventurescência) a finas inclusões de mica crómica (fuchsite) ou de hematite disseminadas numa massa de quartzo microcristalino. A variedade verde, a mais difundida, é extraída em grande quantidade na Índia há séculos.",
            particularites = "A aventurescência, esta cintilação metálica, provém do reflexo da luz nas pintas de mica incluídas; o termo foi depois retomado para designar o vidro artificial que imita este efeito.",
            inclusions = "Plaquetas de fuchsite (mica crómica) dispersas no quartzo, responsáveis pela cintilação característica (aventurescência).",
            lithotherapie = "A aventurina verde é reputada pedra da sorte, associada à fortuna, à abundância e ao apaziguamento emocional."
        ),
        "epidote" to GemTranslation(
            nom = "Epídoto",
            descriptionCourte = "Um verde-pistácio característico, raramente facetado devido ao seu pleocroísmo marcado.",
            descriptionLongue = "O epídoto dá o seu nome a todo um grupo mineral e ocorre em cristais alongados verde-pistácio a verde-oliva, cor que resulta do ferro. O seu forte pleocroísmo, que faz surgir tonalidades diferentes consoante o ângulo de observação, complica a talha de pedras de cor homogénea.",
            particularites = "O forte pleocroísmo (verde, castanho-amarelado, incolor-rosado consoante o ângulo) deve ser tido em conta durante a talha, para revelar a face mais bela e colorida.",
            inclusions = "Forte pleocroísmo e finas inclusões fibrosas ou cristais acessórios consoante o jazigo.",
            lithotherapie = "O epídoto é reputado por favorecer a transformação pessoal e ajudar a libertar padrões emocionais repetitivos."
        ),
        "gaspeite" to GemTranslation(
            nom = "Gaspeíta",
            descriptionCourte = "Um carbonato de níquel verde-maçã opaco, raro e procurado em cabochão.",
            descriptionLongue = "A gaspeíta é um carbonato de níquel de um verde-maçã a verde vivo opaco, descoberto na península de Gaspé, no Quebeque, que lhe dá o nome. Os jazigos australianos exploráveis em qualidade gema são hoje a sua principal fonte comercial.",
            particularites = "Frequentemente confundida à distância com a turquesa ou a variscite devido à sua tonalidade verde opaca, mas distingue-se pela sua cor mais francamente verde-maçã.",
            lithotherapie = "A gaspeíta é associada à abundância e a um enraizamento suave, favorecendo a estabilidade nos períodos de mudança."
        ),
        "hiddenite" to GemTranslation(
            nom = "Hiddenita",
            descriptionCourte = "A variedade verde do espodumênio, colorida pelo crómio, prima da kunzita.",
            descriptionLongue = "A hiddenita é a variedade verde do espodumênio, cor que resulta de vestígios de crómio ou vanádio — ao contrário da kunzita rosa, que deve a sua cor ao manganês. Descoberta na Carolina do Norte no final do século XIX, o melhor material continua a ser americano, embora o Brasil e o Afeganistão também o produzam.",
            particularites = "Tal como todas as variedades de espodumênio, possui uma clivagem perfeita em duas direções e deve ser talhada com precaução.",
            inclusions = "Finas inclusões líquidas e clivagem perfeita em duas direções, como a kunzita, com a qual partilha a espécie (espodumênio).",
            lithotherapie = "A hiddenita é reputada por abrir o coração à compaixão, trazendo simultaneamente clareza e discernimento nas decisões importantes."
        ),
        "angelite" to GemTranslation(
            nom = "Angelite",
            descriptionCourte = "A variedade azul-céu da anidrite, muito apreciada em litoterapia.",
            descriptionLongue = "A angelite é o nome comercial dado à anidrite de um azul pálido e leitoso, polida em cabochões, contas ou peças decorativas. A sua cor provém de vestígios de impurezas no sulfato de cálcio anidro, que se forma quando o gesso é comprimido e perde a sua água ao longo de longos períodos geológicos.",
            particularites = "Risca-se facilmente e teme a humidade prolongada, que pode hidratá-la lentamente em gesso; a proteger da água e dos choques.",
            lithotherapie = "A angelite é associada à comunicação, à serenidade e a uma forma de ligação espiritual apaziguada, daí o seu nome evocativo."
        ),
        "oeil-de-faucon" to GemTranslation(
            nom = "Olho-de-falcão",
            descriptionCourte = "A variante azul-acinzentada chatoyant do olho-de-tigre, não oxidada.",
            descriptionLongue = "O olho-de-falcão partilha a origem do olho-de-tigre: uma pseudomorfose de quartzo após crocidolite (amianto azul), cujas fibras paralelas produzem uma chatoyance sedosa. Ao contrário do olho-de-tigre dourado, conserva a tonalidade azul-acinzentada a azul-esverdeada original, por falta de oxidação do ferro.",
            particularites = "O mesmo bloco de material bruto pode apresentar, localmente, tanto zonas azul-acinzentadas (olho-de-falcão) como zonas douradas (olho-de-tigre), consoante o grau de oxidação do ferro.",
            lithotherapie = "O olho-de-falcão é tradicionalmente associado à clarividência, à visão interior e à capacidade de tomar distância perante situações complexas."
        ),
        "howlite" to GemTranslation(
            nom = "Howlite",
            descriptionCourte = "Uma pedra branca veada de cinzento, frequentemente tingida para imitar a turquesa.",
            descriptionLongue = "A howlite ocorre naturalmente em nódulos brancos de estrutura porosa, atravessados por veios cinzentos a negros evocativos de um mármore. A sua porosidade torna-a fácil de tingir, o que faz dela o material mais frequentemente utilizado para imitar a turquesa a baixo custo — uma prática sempre a verificar antes da compra.",
            particularites = "A sua elevada porosidade torna-a particularmente recetiva a tinturas, na origem de numerosas imitações de turquesa ou de lápis-lazúli no mercado.",
            lithotherapie = "A howlite é reputada por acalmar a mente agitada e favorecer um sono mais sereno."
        ),
        "rhodizite" to GemTranslation(
            nom = "Rodizite",
            descriptionCourte = "Um borato ultrarraro, um dos minerais mais duros depois do corindo.",
            descriptionLongue = "A rodizite é um borato complexo de césio, berílio e alumínio, cristalizando em minúsculos cristais incolores a amarelo pálido encontrados quase exclusivamente em Madagáscar. A sua dureza excecional, próxima da do corindo, e a sua raridade extrema fazem dela uma pedra destinada quase exclusivamente a colecionadores experientes.",
            particularites = "Os cristais facetáveis que ultrapassam um quilate são excecionalmente raros; a maioria das pedras talhadas pesa menos de 0,5 quilates.",
            inclusions = "Espécie muito rara, apresentando-se em pequenos cristais dodecaédricos; as inclusões internas continuam pouco documentadas.",
            lithotherapie = "A rodizite é associada à harmonização energética e à amplificação das intenções positivas."
        ),
        "sanidine" to GemTranslation(
            nom = "Sanidina",
            descriptionCourte = "Um feldspato vulcânico incolor a amarelo pálido, cristalizado rapidamente à superfície.",
            descriptionLongue = "A sanidina é a forma de alta temperatura do feldspato potássico, cristalizando rapidamente em rochas vulcânicas e lavas, o que a distingue da ortóclase, formada mais lentamente em profundidade. Os cristais límpidos e facetáveis mais procurados provêm das projeções vulcânicas do Eifel, na Alemanha.",
            particularites = "Distingue-se da ortóclase pela sua formação vulcânica rápida e pela sua estrutura atómica mais desordenada; ambas partilham a mesma fórmula química.",
            inclusions = "Geralmente limpa, com raras inclusões cristalinas acessórias consoante o jazigo vulcânico de origem.",
            lithotherapie = "A sanidina é associada à clareza mental e à espontaneidade, em eco à sua rápida formação em rocha vulcânica."
        ),
        "tremolite" to GemTranslation(
            nom = "Tremolite",
            descriptionCourte = "Uma anfíbola branca a cinzenta, cuja variedade rosa é bem mais procurada.",
            descriptionLongue = "A tremolite é uma anfíbola cálcio-magnesiana que forma o membro extremo rico em magnésio da série tremolite-actinolite; sob forma fibrosa compacta, constitui um dos componentes da nefrita. A sua variedade gema, geralmente branca, cinzenta ou incolor, é raramente facetada, com exceção da rara variedade violeta dita hexagonite.",
            particularites = "A raríssima variedade rosa-violeta, a hexagonite, deve a sua cor ao manganês e é por vezes confundida com a tanzanite antes de análise.",
            inclusions = "Estrutura fibrosa característica, frequentemente responsável por um efeito chatoyant nas pedras talhadas em cabochão.",
            lithotherapie = "A tremolite é reputada por trazer suavidade e flexibilidade perante a mudança, em eco à sua estrutura fibrosa."
        ),
        "oeil-de-taureau" to GemTranslation(
            nom = "Olho-de-boi",
            descriptionCourte = "O olho-de-tigre aquecido, cuja oxidação do ferro se torna castanho-avermelhada profunda.",
            descriptionLongue = "O olho-de-boi é obtido por aquecimento controlado do olho-de-tigre dourado, um tratamento que intensifica a oxidação do ferro e faz a cor virar do amarelo-castanho para um castanho-avermelhado profundo e intenso, preservando a chatoyance sedosa característica da estrutura fibrosa.",
            particularites = "O tratamento térmico que produz esta tonalidade castanho-avermelhada é comum e amplamente aceite no comércio, desde que divulgado.",
            lithotherapie = "O olho-de-boi é associado à força, ao enraizamento e à determinação, na continuidade simbólica do olho-de-tigre."
        ),
        "unakite" to GemTranslation(
            nom = "Unakite",
            descriptionCourte = "Uma rocha salpicada de verde e rosa, mistura de granito alterado.",
            descriptionLongue = "A unakite é uma rocha granítica alterada, composta por uma mistura característica de feldspato rosa, epídoto verde e quartzo, conferindo-lhe um motivo malhado imediatamente reconhecível. Nomeada a partir dos montes Unaka, na Carolina do Norte, onde foi descrita, é sobretudo talhada em cabochões e contas.",
            particularites = "Sendo uma rocha composta e não um mineral único, a sua dureza e o seu índice de refração variam ligeiramente consoante a proporção de cada componente.",
            lithotherapie = "A unakite é tradicionalmente associada ao equilíbrio afetivo e à cura progressiva após uma provação emocional."
        ),
        "oeil-de-sainte-lucie" to GemTranslation(
            nom = "Olho-de-santa-luzia",
            descriptionCourte = "O opérculo espiralado de um caracol marinho, usado como amuleto desde a Antiguidade.",
            descriptionLongue = "O olho-de-santa-luzia é o opérculo calcário, a pequena «porta» que fecha a abertura da concha de certos gastrópodes marinhos do género Turbo. O seu motivo em espiral castanho e creme, evocativo de um olho, fez dele um amuleto protetor tradicional em numerosas culturas mediterrânicas.",
            particularites = "Não é uma concha, mas sim o opérculo, a peça calcária que fecha a abertura da concha do molusco vivo; desprende-se naturalmente após a morte do animal.",
            lithotherapie = "Usado como pendente desde a Antiguidade, este amuleto é reputado por proteger do mau-olhado e trazer sorte a quem o usa."
        ),
        "jais" to GemTranslation(
            nom = "Azeviche",
            descriptionCourte = "Um carvão fóssil negro fosco, emblema do luto vitoriano.",
            descriptionLongue = "O azeviche é uma variedade compacta de lenhite, madeira fossilizada sob alta pressão ao longo de milhões de anos, polida num negro profundo e aveludado. A sua leveza e a facilidade de talha fizeram dele o material emblemático das joias de luto da época vitoriana, nomeadamente em torno de Whitby, em Inglaterra.",
            particularites = "Aquece rapidamente ao contacto com a pele e pode desenvolver uma carga eletrostática por fricção, tal como o âmbar.",
            lithotherapie = "O azeviche é tradicionalmente associado à proteção contra energias negativas e ao acompanhamento do luto."
        ),
        "grenat-etoile" to GemTranslation(
            nom = "Granada estrelada",
            descriptionCourte = "Uma almandina de quatro ou seis raios luminosos, uma raridade encontrada quase exclusivamente no Idaho.",
            descriptionLongue = "A granada estrelada é uma almandina cujas finas inclusões orientadas (geralmente de rútilo) produzem um asterismo de quatro ou, mais raramente, seis raios sob uma iluminação pontual. Só é conhecida em qualidade gema em dois lugares do mundo: o Idaho, nos Estados Unidos, e alguns jazigos da Índia.",
            particularites = "O Idaho é o único lugar do mundo onde se encontram granadas de asterismo de quatro raios; as estrelas de seis raios, mais raras, provêm dos mesmos jazigos.",
            lithotherapie = "A granada estrelada é associada à força interior e à orientação nos momentos de incerteza."
        ),
        "opale-peruvienne" to GemTranslation(
            nom = "Opala peruana",
            descriptionCourte = "Uma opala opaca azul-esverdeada ou rosa, sem jogo de cores, única no Peru.",
            descriptionLongue = "A opala peruana é uma opala comum opaca, de um azul-esverdeado evocativo da água do mar ou, mais raramente, de um rosa suave — duas tonalidades devidas a vestígios de cobre. Extraída unicamente nos Andes peruanos, é talhada em cabochões para joalharia.",
            particularites = "A sua cor provém de vestígios de cobre, um fenómeno de coloração raro entre as opalas, habitualmente incolores em profundidade.",
            lithotherapie = "A opala peruana é associada ao apaziguamento emocional e à comunicação, em ressonância com a sua tonalidade azul-esverdeada."
        ),
        "opale-commune" to GemTranslation(
            nom = "Opala comum",
            descriptionCourte = "A variedade mais difundida de opala, leitosa e sem jogo de cores.",
            descriptionLongue = "A opala comum, ou opala leitosa, constitui o essencial da produção mundial de opala, mas não apresenta o jogo de cores que dá valor à opala preciosa. Branca, translúcida ou por vezes tingida, é talhada em cabochões a preço acessível.",
            particularites = "A ausência de jogo de cores distingue a opala comum da opala preciosa; ambas partilham, contudo, a mesma composição.",
            lithotherapie = "A opala comum é reputada por trazer suavidade e apaziguamento ao quotidiano."
        ),
        "opale-noire" to GemTranslation(
            nom = "Opala negra",
            descriptionCourte = "O jogo de cores mais espetacular, sobre um fundo escuro que o exalta.",
            descriptionLongue = "A opala negra tira o seu nome do seu fundo escuro, cinzento a negro, sobre o qual o jogo de cores se destaca com uma intensidade inigualável. Extraída quase exclusivamente em Lightning Ridge, em Nova Gales do Sul, é considerada a mais preciosa das opalas.",
            particularites = "O fundo escuro provém de vestígios de carbono e óxidos de ferro entre as esferas de sílica, um fenómeno próprio do jazigo de Lightning Ridge.",
            lithotherapie = "A opala negra é associada à transformação interior e à proteção nos períodos de mudança profunda."
        ),
        "opale-boulder" to GemTranslation(
            nom = "Opala de Boulder",
            descriptionCourte = "Um fino véu de opala sobre a sua matriz de ironstone castanho, deixado intacto na talha.",
            descriptionLongue = "A opala de Boulder forma-se em finas veias no interior de ironstone castanho de Queensland. Em vez de separar a opala da sua rocha hospedeira, demasiado fina e frágil, os lapidários talham a pedra deixando o fundo castanho natural, o que realça o jogo de cores.",
            particularites = "Ao contrário das restantes opalas, inclui deliberadamente a sua rocha hospedeira, o que a torna mais resistente a choques do que uma opala sólida.",
            lithotherapie = "A opala de Boulder é associada ao enraizamento e à solidez, em ressonância com a rocha que a suporta."
        ),
        "opale-ethiopie" to GemTranslation(
            nom = "Opala da Etiópia",
            descriptionCourte = "Uma opala de jogo de cores vivo sobre um fundo amelado, mas hidrófana e por isso sensível à água.",
            descriptionLongue = "Descoberta nos anos 2010 na região de Wollo, a opala da Etiópia revolucionou o mercado pelo seu jogo de cores particularmente vivo sobre um fundo translúcido mel a incolor. A sua natureza hidrófana — absorve água como uma esponja — torna-a, porém, instável se for imersa ou demasiado exposta à humidade.",
            particularites = "Natureza hidrófana: pode absorver até 20% do seu volume em água, fissurar-se ao secar e sofrer uma alteração temporária da transparência ao contacto com a humidade.",
            inclusions = "Natureza hidrófana (porosa) que pode absorver água e alterar temporariamente a sua transparência; estrutura interna de esferas de sílica responsável pelo jogo de cores.",
            lithotherapie = "A opala da Etiópia é reputada por amplificar as emoções e a criatividade, tal como as restantes opalas preciosas."
        ),
        "marcassite" to GemTranslation(
            nom = "Marcassita",
            descriptionCourte = "O polimorfo ortorrômbico e mais pálido da pirite, em leques metálicos dentro de nódulos de sílex.",
            descriptionLongue = "Quimicamente idêntica à pirite (FeS₂), mas cristalizando no sistema ortorrômbico, a marcassita forma agregados em leque ou em «crista de galo» de um amarelo bronze mais pálido e prateado. É encontrada tipicamente em nódulos no interior de sílex e giz, ou associada a jazidas de carvão. Mais instável que a pirite, decompõe-se mais facilmente com exposição prolongada à umidade.",
            particularites = "A «joalheria de marcassita» histórica (georgiana, vitoriana, art déco) utiliza na realidade quase sempre pirite lapidada em facetas: a verdadeira marcassita, demasiado frágil e instável, não se presta à lapidação.",
            lithotherapie = "Como a pirite, a marcassita é associada à proteção e ao enraizamento, com uma reputação particular de acalmar a mente e trazer clareza."
        ),
        "astrophyllite" to GemTranslation(
            nom = "Astrofilita",
            descriptionCourte = "Feixes dourados em forma de estrela, presos numa rocha escura.",
            descriptionLongue = "A astrofilita deve o seu nome ao grego «astron» (estrela) e «phyllon» (folha): suas finas lâminas de tom cobre a dourado-bronze se estendem em feixes radiantes que evocam explosões estelares, geralmente engastadas numa rocha hospedeira escura (egirina, feldspato). Sempre trabalhada em cabochão para revelar este motivo espetacular, provém quase exclusivamente dos maciços alcalinos da península de Kola.",
            particularites = "Clivagem perfeita numa direção (estrutura em lâminas, como a mica), o que a torna quebradiça e impõe um corte em cabochão em vez de facetado.",
            lithotherapie = "A astrofilita é reputada por favorecer a introspecção e a clareza mental, em ressonância com o seu motivo que evoca as estrelas."
        ),
    )
}
